-- AKU Mathematics, batch 2: 248 original MCQs, MAT-0246 to MAT-0493.
-- 1) Gap topics: skills that appear in AKU's Mathematics Reasoning practice set (aku.edu, admissions/Documents/
--    pr-mbbs-mathematics-reasoning.pdf) but were thin or missing in batch 1 (MAT-0001..0245): unit conversion,
--    clock and calendar time, transformations, triangle inequality, packing, area/volume scale factors, ordering
--    fractions/decimals/percentages, best buys, expressions from words, AKU-style quantity comparisons (pie chart,
--    sets, grouped data, median with an unknown) and the "which two statements together are sufficient" format.
-- 2) About 200 hard questions spread over all ten chapters.
-- Written for Markhor Prep, not copied from AKU or any book. Every key was recomputed by a script; comparison and
-- data-sufficiency keys were found by brute force over all allowed cases.
--
-- Mathematics is only on the AKU test, so every question has questions.mdcat = 0 (out of the MDCAT bank and the mocks)
-- and is listed in the AKU bank under its own chapter. Not in the free set. INSERT OR IGNORE keeps the file safe to
-- run twice; if the site owner's admin account doesn't exist (a fresh local database) nothing is inserted.
-- Inserted in batches of 20 to stay under D1's statement size limit.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0246', 'Arithmetic and number', 'Time and clocks', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A night shift starts at 9:45 p.m. and ends at 6:20 a.m. the next day. How many minutes long is it?', '["515", "205", "575", "835"]', 0, '9:45 p.m. to 5:45 a.m. is 8 h; to 6:20 a.m. is 35 min more. 8 × 60 + 35 = 515 minutes.', '{"1": "Subtracts 6:20 from 9:45 as if both were in the same half of the day.", "2": "Counts 9 hours 35 minutes, one hour too many.", "3": "Writes 8 h 35 min as the number 835."}'),
  ('MAT-0247', 'Arithmetic and number', 'Time and clocks', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A flight leaves Karachi at 23:30 Pakistan time and takes 7 hours 45 minutes to reach London. London time is 5 hours behind Pakistan time. What is the local time in London when it lands?', '["07:15", "12:15", "02:15", "03:15"]', 2, '23:30 + 7 h 45 min = 07:15 next day, Pakistan time. London is 5 hours behind: 07:15 − 5 h = 02:15.', '{"0": "That is the landing time in Pakistan time.", "1": "Adds the 5 hours instead of subtracting them.", "3": "Takes London as 4 hours behind."}'),
  ('MAT-0248', 'Arithmetic and number', 'Time and clocks', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Today is Wednesday. What day of the week will it be 100 days from today?', '["Friday", "Thursday", "Wednesday", "Saturday"]', 0, '100 = 14 × 7 + 2. After 14 whole weeks it is Wednesday again; 2 more days gives Friday.', '{"1": "Uses a remainder of 1 instead of 2 (100 = 14 × 7 + 2).", "2": "Assumes 100 days is a whole number of weeks.", "3": "Uses a remainder of 3."}'),
  ('MAT-0249', 'Arithmetic and number', 'Time and clocks', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A clock gains 3 minutes every hour. It is set to the correct time at 8:00 a.m. What time does it show when the correct time is 8:00 p.m. the same day?', '["8:03 p.m.", "8:36 p.m.", "8:24 p.m.", "7:24 p.m."]', 1, 'From 8 a.m. to 8 p.m. is 12 hours, so the clock gains 12 × 3 = 36 minutes. It shows 8:36 p.m.', '{"0": "Adds only one hour''s gain.", "2": "Counts 8 hours instead of 12.", "3": "Subtracts the gain, as if the clock were slow."}'),
  ('MAT-0250', 'Arithmetic and number', 'Factorials', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many zeros are at the end of 50! (50 factorial)?', '["10", "5", "12", "11"]', 2, 'Each trailing zero needs a factor 10 = 2 × 5, and 5s are scarcer than 2s. Multiples of 5 up to 50 give 10 fives; 25 and 50 each give one more (they contain 5²). Total 12.', '{"0": "Counts only the multiples of 5 (50 ÷ 5 = 10) and misses that 25 and 50 each give an extra 5.", "1": "Counts only the multiples of 10.", "3": "Adds just one extra 5 for 25 and forgets the second one from 50."}'),
  ('MAT-0251', 'Arithmetic and number', 'Remainders', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the remainder when 7¹⁰⁰ is divided by 5?', '["2", "1", "4", "3"]', 1, 'Remainders of powers of 7 on division by 5 cycle 2, 4, 3, 1 (length 4). 100 is a multiple of 4, so 7¹⁰⁰ is at the end of a cycle: remainder 1.', '{"0": "That is the remainder of 7¹, not 7¹⁰⁰.", "2": "That is the remainder of 7², the second step of the cycle.", "3": "That is the remainder of 7³."}'),
  ('MAT-0252', 'Arithmetic and number', 'Units digits', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the units digit of 3⁴⁷ + 7²³?', '["0", "4", "6", "8"]', 0, 'Units digits of powers of 3 cycle 3, 9, 7, 1 and of 7 cycle 7, 9, 3, 1. 47 leaves 3 on division by 4, so 3⁴⁷ ends in 7; 23 leaves 3, so 7²³ ends in 3. 7 + 3 = 10, units digit 0.', '{"1": "Takes 3⁴⁷ as ending in 1 (as if 47 were a multiple of 4) and 7²³ as ending in 3.", "2": "Takes 3⁴⁷ as ending in 3 and 7²³ in 3.", "3": "Takes 3⁴⁷ as ending in 1 and 7²³ as ending in 7."}'),
  ('MAT-0253', 'Arithmetic and number', 'Factors and multiples', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many positive whole-number divisors does 360 have?', '["20", "12", "18", "24"]', 3, '360 = 2³ × 3² × 5¹. The number of divisors is (3 + 1)(2 + 1)(1 + 1) = 4 × 3 × 2 = 24.', '{"0": "Miscounts one of the prime powers in 360 = 2³ × 3² × 5.", "1": "Uses (3)(2)(1) + … instead of adding 1 to each exponent.", "2": "Takes the exponent of 2 as 2 instead of 3."}'),
  ('MAT-0254', 'Arithmetic and number', 'Remainders', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the smallest whole number greater than 2 that leaves a remainder of 2 when divided by each of 3, 4, 5 and 6?', '["62", "122", "362", "58"]', 0, 'The number minus 2 must be a common multiple of 3, 4, 5 and 6. Their LCM is 60, so the smallest such number above 2 is 60 + 2 = 62.', '{"1": "That is the next such number, not the smallest.", "2": "Uses the product 3 × 4 × 5 × 6 = 360 instead of the LCM.", "3": "Subtracts 2 from the LCM instead of adding it."}'),
  ('MAT-0255', 'Arithmetic and number', 'Factors and multiples', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two numbers have a highest common factor (HCF) of 12 and a lowest common multiple (LCM) of 360. One of them is 72. What is the other?', '["30", "60", "5", "90"]', 1, 'For two numbers, product = HCF × LCM. Other number = 12 × 360 ÷ 72 = 60. Check: HCF(72, 60) = 12 and LCM = 360.', '{"0": "Its HCF with 72 would be 6, not 12.", "2": "Divides the LCM by 72 and forgets to multiply by the HCF.", "3": "Its HCF with 72 would be 18, not 12."}'),
  ('MAT-0256', 'Arithmetic and number', 'Divisibility', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the sum of all two-digit numbers that are divisible by 7?', '["735", "833", "630", "728"]', 3, 'The multiples are 14, 21, …, 98: 13 terms. Sum = 13 × (14 + 98) ÷ 2 = 13 × 56 = 728.', '{"0": "Includes 7, which is a one-digit number.", "1": "Includes 105, which has three digits.", "2": "Leaves out 98, the largest two-digit multiple of 7."}'),
  ('MAT-0257', 'Arithmetic and number', 'Divisibility', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many whole numbers from 1 to 1000 are divisible by none of 2, 3 and 5?', '["734", "267", "266", "333"]', 2, 'Divisible by 2, 3 or 5: 500 + 333 + 200 − 166 − 100 − 66 + 33 = 734 (inclusion–exclusion). Divisible by none: 1000 − 734 = 266.', '{"0": "That is how many ARE divisible by at least one of them.", "1": "Off by one: counts 1000 or misses the inclusion–exclusion correction for 30.", "3": "Removes only the multiples of 2 and 3 (1000 − 500 − 333 + 166) and forgets 5."}'),
  ('MAT-0258', 'Arithmetic and number', 'Recurring decimals', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Write 0.272727… + 0.333… (both recurring) as a single fraction in lowest terms.', '["57/100", "6/11", "20/33", "3/5"]', 2, '0.2727… = 27/99 = 3/11 and 0.333… = 1/3. 3/11 + 1/3 = 9/33 + 11/33 = 20/33.', '{"0": "Uses 0.27 + 0.3 and ignores the recurring digits.", "1": "Adds 27/99 + 27/99 instead of 27/99 + 3/9.", "3": "Rounds the decimals to 0.27 + 0.33 = 0.60."}'),
  ('MAT-0259', 'Arithmetic and number', 'Estimation', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Work out (0.0049 × 81,000) ÷ (0.7 × 0.009).', '["6,300", "63,000", "630,000", "56,700"]', 1, 'Numerator: 0.0049 × 81,000 = 396.9. Denominator: 0.7 × 0.009 = 0.0063. 396.9 ÷ 0.0063 = 63,000. (Quick check: 49 × 81 ÷ (7 × 9) = 7 × 9 = 63, then fix the powers of ten.)', '{"0": "Loses a power of ten when dividing by 0.0063.", "2": "Gains a power of ten when dividing by 0.0063.", "3": "Uses 0.7 × 0.009 = 0.007 instead of 0.0063."}'),
  ('MAT-0260', 'Arithmetic and number', 'Powers and roots', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which of these is the largest?', '["√2", "⁵√5 (the fifth root of 5)", "⁶√6 (the sixth root of 6)", "∛3 (the cube root of 3)"]', 3, 'Compare by raising to a common power: (√2)⁶ = 8 and (∛3)⁶ = 9, so ∛3 > √2. ∛3 ≈ 1.442, ⁵√5 ≈ 1.380, ⁶√6 ≈ 1.348. ∛3 is largest.', '{"0": "√2 ≈ 1.414, smaller than ∛3 ≈ 1.442.", "1": "⁵√5 ≈ 1.380.", "2": "⁶√6 ≈ 1.348."}'),
  ('MAT-0261', 'Arithmetic and number', 'Powers and roots', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Simplify (2¹⁰ + 2⁹) ÷ (2⁸ − 2⁷).', '["12", "1,536", "6", "24"]', 0, 'Top: 2⁹(2 + 1) = 3 × 2⁹. Bottom: 2⁷(2 − 1) = 2⁷. Ratio = 3 × 2² = 12.', '{"1": "That is only the top (2¹⁰ + 2⁹); it still has to be divided by 2⁸ − 2⁷ = 128.", "2": "Factorises the top as 2⁹ × 3 but the bottom as 2⁸ instead of 2⁷.", "3": "Factorises the bottom as 2⁶ instead of 2⁷."}'),
  ('MAT-0262', 'Arithmetic and number', 'Powers and roots', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The expression √(12 + √(12 + √(12 + …))) continues for ever. What is its value?', '["3", "2√3", "4", "6"]', 2, 'Call the value x. Then x = √(12 + x), so x² − x − 12 = 0, (x − 4)(x + 3) = 0. x is positive, so x = 4.', '{"0": "Solves x² = 12 − x instead of x² = 12 + x.", "1": "That is just √12, the first layer.", "3": "Guesses half of 12."}'),
  ('MAT-0263', 'Arithmetic and number', 'Primes', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many prime numbers lie between 50 and 100?', '["10", "9", "11", "12"]', 0, 'They are 53, 59, 61, 67, 71, 73, 79, 83, 89 and 97: ten primes.', '{"1": "Misses one, often 53 or 97.", "2": "Counts 51 or 91 as prime (51 = 3 × 17, 91 = 7 × 13).", "3": "Counts both 51 and 91 as prime."}'),
  ('MAT-0264', 'Arithmetic and number', 'Fractions', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'a and b are positive numbers with a/b = 0.375 and b − a = 15. What is a + b?', '["24", "11", "55", "33"]', 3, '0.375 = 3/8, so a = 3k and b = 8k. b − a = 5k = 15 gives k = 3, a = 9, b = 24, and a + b = 33.', '{"0": "That is b alone.", "1": "That is 3 + 8, the ratio parts, not the actual numbers.", "2": "Uses b − a = 3 parts instead of 8 − 3 = 5 parts, so takes one part as 5."}'),
  ('MAT-0265', 'Arithmetic and number', 'Standard form', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Work out (6.4 × 10⁵) ÷ (8 × 10⁻³) and give the answer in standard form.', '["8 × 10²", "8 × 10⁷", "8 × 10⁸", "1.25 × 10⁷"]', 1, '6.4 ÷ 8 = 0.8 and 10⁵ ÷ 10⁻³ = 10⁸. So 0.8 × 10⁸ = 8 × 10⁷.', '{"0": "Subtracts the powers as 5 − 3 instead of 5 − (−3).", "2": "Forgets that 6.4 ÷ 8 = 0.8 needs one power of ten moved.", "3": "Divides 8 by 6.4 instead of 6.4 by 8."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0266', 'Arithmetic and number', 'Remainders', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the remainder when 5⁴³ is divided by 7?', '["1", "5", "4", "6"]', 1, 'Remainders of 5, 5², 5³, … on division by 7 cycle 5, 4, 6, 2, 3, 1 (length 6). 43 = 6 × 7 + 1, so 5⁴³ is at the first step of a cycle: remainder 5.', '{"0": "That is the remainder of 5⁴² (42 is a multiple of the cycle length 6); one more factor of 5 is needed.", "2": "That is the remainder of 5².", "3": "That is the remainder of 5³."}'),
  ('MAT-0267', 'Arithmetic and number', 'Factors and multiples', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the smallest positive whole number n for which 180n is a perfect square?', '["5", "20", "10", "45"]', 0, '180 = 2² × 3² × 5. Only the 5 has an odd power, so multiplying by 5 gives 2² × 3² × 5² = 900 = 30².', '{"1": "180 × 20 = 3,600 is a square, but 5 is smaller.", "2": "180 × 10 = 1,800 is not a perfect square.", "3": "180 × 45 = 8,100 is a square, but 5 is smaller."}'),
  ('MAT-0268', 'Arithmetic and number', 'Absolute value', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many integers x satisfy |x − 3| < 5?', '["10", "11", "5", "9"]', 3, '|x − 3| < 5 means −5 < x − 3 < 5, so −2 < x < 8. The integers are −1, 0, 1, …, 7: nine of them.', '{"0": "Includes an end point (−2 or 8), but the inequality is strict.", "1": "Includes both end points −2 and 8.", "2": "Counts only the positive integers that work."}'),
  ('MAT-0269', 'Arithmetic and number', 'Fractions', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which of these fractions is the largest?', '["13/21", "11/18", "5/8", "7/12"]', 2, 'As decimals: 7/12 ≈ 0.583, 5/8 = 0.625, 11/18 ≈ 0.611, 13/21 ≈ 0.619. The largest is 5/8.', '{"0": "13/21 ≈ 0.619, just below 5/8 = 0.625.", "1": "11/18 ≈ 0.611.", "3": "7/12 ≈ 0.583."}'),
  ('MAT-0270', 'Percentages', 'Fractions, decimals and percentages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which list is in order from smallest to largest?', '["3/8, 37%, 0.38, 0.4", "0.4, 0.38, 3/8, 37%", "37%, 3/8, 0.38, 0.4", "37%, 0.38, 3/8, 0.4"]', 2, 'As decimals: 37% = 0.37, 3/8 = 0.375, 0.38, 0.4. So 37% < 3/8 < 0.38 < 0.4.', '{"0": "3/8 = 0.375 is larger than 37% = 0.37.", "1": "This is largest to smallest.", "3": "3/8 = 0.375 is smaller than 0.38."}'),
  ('MAT-0271', 'Percentages', 'Fractions, decimals and percentages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which of these is the smallest?', '["5/12", "41%", "0.42", "4/9"]', 1, 'As decimals: 5/12 ≈ 0.4167, 0.42, 41% = 0.41, 4/9 ≈ 0.4444. The smallest is 41%.', '{"0": "5/12 ≈ 0.417, a little more than 0.41.", "2": "0.42 is more than 0.41.", "3": "4/9 ≈ 0.444."}'),
  ('MAT-0272', 'Percentages', 'Fractions, decimals and percentages', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Write 0.0035 as a percentage.', '["3.5%", "35%", "0.035%", "0.35%"]', 3, 'To change a decimal to a percentage, multiply by 100: 0.0035 × 100 = 0.35%.', '{"0": "Multiplies by 1,000 instead of 100.", "1": "Multiplies by 10,000.", "2": "Multiplies by 10."}'),
  ('MAT-0273', 'Percentages', 'Successive percentages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A price is raised by 25% and the new price is then cut by 20%. What is the overall change?', '["5% increase", "No change", "5% decrease", "1% decrease"]', 1, 'Multipliers: 1.25 × 0.80 = 1.00. The final price equals the original price.', '{"0": "Adds +25 and −20 as if the percentages were of the same amount.", "2": "Gets the sign of the simple difference wrong as well.", "3": "Uses (1.1)(0.9) as for equal ±10% changes."}'),
  ('MAT-0274', 'Percentages', 'Successive percentages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A shop gives a 20% discount and then a further 15% off the reduced price. What single discount is this equal to?', '["32%", "35%", "30%", "3%"]', 0, 'The customer pays 0.80 × 0.85 = 0.68 of the price, so the single discount is 1 − 0.68 = 32%.', '{"1": "Adds the two discounts; the second applies to a smaller price.", "2": "Underestimates; 0.80 × 0.85 = 0.68 leaves 68%.", "3": "Multiplies 20% × 15% instead of the multipliers."}'),
  ('MAT-0275', 'Percentages', 'Successive percentages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A salary is increased by x% and the new salary is then decreased by x%. The final salary is 4% less than the original. What is x?', '["2", "4", "20", "10"]', 2, '(1 + x/100)(1 − x/100) = 1 − x²/10,000 = 0.96, so x²/10,000 = 0.04, x² = 400 and x = 20.', '{"0": "Halves the 4% loss.", "1": "Assumes the loss equals x.", "3": "With x = 10 the multiplier is 1.1 × 0.9 = 0.99, only a 1% loss."}'),
  ('MAT-0276', 'Percentages', 'Reverse percentages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The price of a phone including 15% sales tax is Rs 27,600. What is the price before tax?', '["Rs 23,460", "Rs 31,740", "Rs 4,140", "Rs 24,000"]', 3, 'Rs 27,600 is 115% of the pre-tax price. Pre-tax = 27,600 ÷ 1.15 = Rs 24,000.', '{"0": "Takes 15% off Rs 27,600; the tax was 15% of the smaller, pre-tax price.", "1": "Adds 15% instead of removing it.", "2": "That is 15% of Rs 27,600, not the pre-tax price."}'),
  ('MAT-0277', 'Percentages', 'Percentage change', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A town''s population grows by 10% every year. It is 145,200 now. What was it 2 years ago?', '["120,000", "116,160", "121,000", "130,680"]', 0, 'Two years of growth multiply by 1.1² = 1.21. 145,200 ÷ 1.21 = 120,000.', '{"1": "Takes 20% off the current figure.", "2": "Divides by 1.2 (adding the two 10% rises) instead of by 1.1² = 1.21.", "3": "Takes 10% off the current figure (one year only, and on the wrong base)."}'),
  ('MAT-0278', 'Percentages', 'Compound interest', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Rs 50,000 is invested at 8% a year, compounded annually. How much interest is earned in 2 years?', '["Rs 8,000", "Rs 4,000", "Rs 8,320", "Rs 58,320"]', 2, 'Amount = 50,000 × 1.08² = 50,000 × 1.1664 = 58,320. Interest = 58,320 − 50,000 = Rs 8,320.', '{"0": "That is simple interest (2 × 8% of 50,000).", "1": "That is one year''s interest.", "3": "That is the final amount, not the interest."}'),
  ('MAT-0279', 'Percentages', 'Percentages in context', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '40 litres of a solution is 25% alcohol. How many litres of water must be added to make it 20% alcohol?', '["2 litres", "10 litres", "8 litres", "50 litres"]', 1, 'Alcohol = 25% of 40 = 10 L, and it stays the same. For 20%: total = 10 ÷ 0.20 = 50 L. Water to add = 50 − 40 = 10 L.', '{"0": "Adds 5% of 40 litres, as if the 5-point drop were a share of the volume.", "2": "Takes 20% of 40 litres.", "3": "That is the final volume, not the water added."}'),
  ('MAT-0280', 'Percentages', 'Percentages in context', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Asma scored 20% more marks than Bilal. By what percentage are Bilal''s marks less than Asma''s?', '["20%", "25%", "83⅓%", "16⅔%"]', 3, 'Let Bilal = 100, Asma = 120. The difference 20 as a percentage of 120 is 20 ÷ 120 = 1/6 = 16⅔%.', '{"0": "Uses Bilal''s marks as the base again; the base is now Asma''s.", "1": "Inverts 1.2 wrongly as 1.25.", "2": "That is Bilal''s marks as a percentage of Asma''s, not how much less they are."}'),
  ('MAT-0281', 'Percentages', 'Percentage change', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The length of a rectangle is increased by 20% and its width is decreased by 20%. What happens to its area?', '["It decreases by 4%", "It does not change", "It increases by 4%", "It decreases by 40%"]', 0, 'New area = 1.2 × 0.8 = 0.96 of the old area, a 4% decrease.', '{"1": "Assumes +20% and −20% cancel; 1.2 × 0.8 = 0.96.", "2": "Gets the sign wrong.", "3": "Adds 20 + 20 for the decrease."}'),
  ('MAT-0282', 'Percentages', 'Percentage change', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The radius of a circle is increased by 10%. By what percentage does its area increase?', '["10%", "21%", "20%", "33.1%"]', 1, 'Area ∝ r². New area = 1.1² = 1.21 of the old, a 21% increase.', '{"0": "Area depends on the square of the radius.", "2": "Doubles 10% but forgets the 1% cross term.", "3": "That is the change for a volume (cube of the length)."}'),
  ('MAT-0283', 'Percentages', 'Percentage points', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A school''s pass rate rose from 40% to 50%. By what percentage did the pass rate increase?', '["10%", "20%", "25%", "50%"]', 2, 'The rate rose by 10 percentage points. As a percentage of the old rate: 10 ÷ 40 = 25%.', '{"0": "That is the rise in percentage points, not the percentage increase.", "1": "Divides the 10-point rise by 50 instead of 40.", "3": "Confuses the new rate with the change."}'),
  ('MAT-0284', 'Percentages', 'Profit and loss', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Selling a bag for Rs 1,380 gives a 15% profit. At what price must it be sold to make a 25% profit?', '["Rs 1,200", "Rs 1,725", "Rs 1,518", "Rs 1,500"]', 3, 'Cost = 1,380 ÷ 1.15 = Rs 1,200. For 25% profit: 1,200 × 1.25 = Rs 1,500.', '{"0": "That is the cost price.", "1": "Takes 25% profit on Rs 1,380 instead of on the cost.", "2": "Adds 10% of Rs 1,380."}'),
  ('MAT-0285', 'Percentages', 'Profit and loss', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A shopkeeper marks goods 40% above cost and then gives a 10% discount on the marked price. What is the profit percentage?', '["30%", "126%", "26%", "50%"]', 2, 'Selling price = 1.40 × 0.90 = 1.26 of cost, a 26% profit.', '{"0": "Subtracts 10 from 40.", "1": "That is the selling price as a percentage of cost, not the profit.", "3": "Adds the markup and discount."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0286', 'Percentages', 'Profit and loss', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two watches are each sold for Rs 1,200. One is sold at a 20% profit and the other at a 20% loss. What is the overall result?', '["No profit or loss", "A loss of 4%", "A loss of 2%", "A profit of 4%"]', 1, 'Costs: 1,200 ÷ 1.2 = 1,000 and 1,200 ÷ 0.8 = 1,500, total 2,500. Sales total 2,400. Loss = 100, which is 100 ÷ 2,500 = 4%.', '{"0": "The 20% figures are of different cost prices, so they do not cancel.", "2": "Halves the correct loss.", "3": "Gets the direction wrong."}'),
  ('MAT-0287', 'Percentages', 'Percentages in context', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Fresh grapes are 90% water by mass. Dried grapes (raisins) are 20% water. How many kilograms of raisins can be made from 40 kg of fresh grapes?', '["4 kg", "8 kg", "32 kg", "5 kg"]', 3, 'Dry matter = 10% of 40 = 4 kg. In raisins, the dry matter is 80% of the mass, so mass = 4 ÷ 0.80 = 5 kg.', '{"0": "That is the dry matter alone, without the 20% water raisins still hold.", "1": "Takes 20% of 40 kg.", "2": "Removes only 20% of the mass."}'),
  ('MAT-0288', 'Percentages', 'Percentages in context', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In an election between two candidates, the winner got 55% of the valid votes and won by 3,000 votes. How many valid votes were cast?', '["30,000", "5,455", "6,000", "60,000"]', 0, 'The loser got 45%, so the margin is 55% − 45% = 10% of the valid votes. 10% = 3,000, so the total is 30,000.', '{"1": "Divides 3,000 by 0.55.", "2": "Treats the 3,000-vote margin as 50% of the votes.", "3": "Takes the margin as 55% − 50% = 5% of the votes."}'),
  ('MAT-0289', 'Percentages', 'Percentages in context', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a class, 30% of the students are girls. 40% of the girls and 60% of the boys passed a test. What percentage of the whole class passed?', '["50%", "54%", "46%", "60%"]', 1, 'Out of 100 students: 30 girls (12 pass) and 70 boys (42 pass). 54 of 100 passed: 54%.', '{"0": "Averages 40% and 60% without weighting.", "2": "Swaps the weights (70% girls, 30% boys).", "3": "Uses only the boys'' pass rate."}'),
  ('MAT-0290', 'Percentages', 'Percentage change', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The price of sugar rises by 25%. By what percentage must a family reduce its use of sugar so that its spending on sugar stays the same?', '["25%", "80%", "20%", "33⅓%"]', 2, 'Spending = price × amount. With price × 1.25, the amount must be × 1/1.25 = 0.8, a 20% cut.', '{"0": "The reduction is a percentage of the old amount, and 0.75 × 1.25 ≠ 1.", "1": "That is the new amount as a percentage of the old.", "3": "Uses 25 ÷ 75 instead of 25 ÷ 125."}'),
  ('MAT-0291', 'Percentages', 'Percentage change', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The side of a square is measured 5% too long. By what percentage is its area, calculated from this measurement, too large?', '["10.25%", "10%", "5%", "25%"]', 0, 'Calculated area = (1.05 s)² = 1.1025 s², which is 10.25% too large.', '{"1": "Doubles 5% but leaves out the 0.25% cross term.", "2": "Area depends on the square of the side.", "3": "Squares 5 instead of 1.05."}'),
  ('MAT-0292', 'Percentages', 'Simple interest', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A sum of money doubles in 8 years at simple interest. How many years will it take to triple at the same rate?', '["12 years", "24 years", "20 years", "16 years"]', 3, 'Doubling means interest = 100% of the sum in 8 years, so 12.5% a year. Tripling needs 200% interest: 200 ÷ 12.5 = 16 years.', '{"0": "Takes half again of 8 years.", "1": "Multiplies 8 by 3.", "2": "Adds 12 years to 8."}'),
  ('MAT-0293', 'Ratio, rates and proportion', 'Unit conversion', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A temperature is 98.6 °F. What is it in °C? (Use C = 5/9 × (F − 32).)', '["37 °C", "66.6 °C", "54.8 °C", "209.5 °C"]', 0, 'C = 5/9 × (98.6 − 32) = 5/9 × 66.6 = 37 °C.', '{"1": "Subtracts 32 but does not multiply by 5/9.", "2": "Multiplies by 5/9 without subtracting 32 first.", "3": "Uses the °C-to-°F formula the wrong way round."}'),
  ('MAT-0294', 'Ratio, rates and proportion', 'Unit conversion', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A patient''s temperature is 40 °C. What is it in °F? (Use F = 9/5 × C + 32.)', '["72 °F", "104 °F", "54.2 °F", "4.4 °F"]', 1, 'F = 9/5 × 40 + 32 = 72 + 32 = 104 °F.', '{"0": "Adds 32 but does not multiply by 9/5.", "2": "Multiplies by 5/9 instead of 9/5.", "3": "Uses the °F-to-°C formula."}'),
  ('MAT-0295', 'Ratio, rates and proportion', 'Unit conversion', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A car travels at 90 km/h. What is this speed in metres per second?', '["324 m/s", "1.5 m/s", "25 m/s", "250 m/s"]', 2, '1 km/h = 1,000 m ÷ 3,600 s = 1/3.6 m/s. 90 ÷ 3.6 = 25 m/s.', '{"0": "Multiplies by 3.6 instead of dividing.", "1": "Divides by 60 only (km per minute, not m/s).", "3": "Multiplies by 1,000 but divides by 360 instead of 3,600."}'),
  ('MAT-0296', 'Ratio, rates and proportion', 'Unit conversion', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A sheet of glass has an area of 2.5 m². What is its area in cm²?', '["250 cm²", "2,500 cm²", "250,000 cm²", "25,000 cm²"]', 3, '1 m = 100 cm, so 1 m² = 100 × 100 = 10,000 cm². 2.5 × 10,000 = 25,000 cm².', '{"0": "Multiplies by 100, as if converting a length.", "1": "Multiplies by 1,000.", "2": "Multiplies by 100,000."}'),
  ('MAT-0297', 'Ratio, rates and proportion', 'Unit conversion', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A water tank holds 0.45 m³. How many litres is this? (1 litre = 1,000 cm³.)', '["45 litres", "4,500 litres", "450,000 litres", "450 litres"]', 3, '1 m³ = 100³ = 1,000,000 cm³ = 1,000 litres. 0.45 × 1,000 = 450 litres.', '{"0": "Multiplies by 100.", "1": "Multiplies by 10,000.", "2": "Converts to cm³ but forgets to divide by 1,000."}'),
  ('MAT-0298', 'Ratio, rates and proportion', 'Unit conversion', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A syrup contains 250 mg of medicine in every 5 mL. How many mL give a dose of 400 mg?', '["3.125 mL", "8 mL", "80 mL", "0.8 mL"]', 1, 'The syrup has 250 ÷ 5 = 50 mg per mL. 400 ÷ 50 = 8 mL.', '{"0": "Divides the other way: 250 ÷ 400 × 5.", "2": "Divides 400 by 5.", "3": "Loses a factor of 10."}'),
  ('MAT-0299', 'Ratio, rates and proportion', 'Best buys', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Rice is sold in four pack sizes: 1 kg for Rs 300, 2 kg for Rs 590, 5 kg for Rs 1,450 and 10 kg for Rs 2,850. Which pack gives the lowest price per kilogram?', '["10 kg for Rs 2,850", "5 kg for Rs 1,450", "2 kg for Rs 590", "1 kg for Rs 300"]', 0, 'Per kg: 300, 295, 290 and 285 rupees. The 10 kg pack is cheapest per kilogram.', '{"1": "That is Rs 290 per kg; the 10 kg pack is Rs 285.", "2": "That is Rs 295 per kg.", "3": "That is the cheapest pack, but the dearest per kg."}'),
  ('MAT-0300', 'Ratio, rates and proportion', 'Best buys', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Juice costs Rs 270 for a 1.5-litre bottle or Rs 50 for a 250 mL carton. How much cheaper per litre is the bottle?', '["Rs 220", "Rs 5", "Rs 20", "Rs 180"]', 2, 'Bottle: 270 ÷ 1.5 = Rs 180 per litre. Carton: 50 × 4 = Rs 200 per litre. Difference Rs 20.', '{"0": "Compares the two prices directly, ignoring the sizes.", "1": "Compares the price per 250 mL (Rs 45 against Rs 50).", "3": "That is the bottle''s price per litre, not the difference."}'),
  ('MAT-0301', 'Ratio, rates and proportion', 'Combining ratios', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A : B = 2 : 3 and B : C = 4 : 5. What is A : B : C?', '["2 : 3 : 5", "8 : 12 : 15", "2 : 12 : 5", "8 : 12 : 10"]', 1, 'Make B the same: A : B = 8 : 12 and B : C = 12 : 15. So A : B : C = 8 : 12 : 15.', '{"0": "Joins the ratios without making B the same in both.", "2": "Scales only B.", "3": "Scales the second ratio by 2 instead of 3."}'),
  ('MAT-0302', 'Ratio, rates and proportion', 'Work rates', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Pipe A fills a tank in 6 hours and pipe B fills it in 8 hours. Pipe C empties the full tank in 12 hours. If all three are opened together on an empty tank, how long does it take to fill?', '["2 h 40 min", "3 h 26 min", "4 h 48 min", "24 h 0 min"]', 2, 'Per hour: 1/6 + 1/8 − 1/12 = 4/24 + 3/24 − 2/24 = 5/24 of the tank. Time = 24/5 h = 4.8 h = 4 h 48 min.', '{"0": "Treats C as a filling pipe too (1/6 + 1/8 + 1/12 = 9/24).", "1": "Ignores pipe C (A and B alone take 24/7 h).", "3": "Uses only B and C (1/8 − 1/12 = 1/24) and forgets A."}'),
  ('MAT-0303', 'Ratio, rates and proportion', 'Work rates', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '12 workers can finish a job in 15 days. They work together for 5 days, and then 4 of them leave. How many more days do the remaining workers need to finish?', '["15", "10", "22.5", "30"]', 0, 'Total work = 12 × 15 = 180 worker-days. After 5 days, 60 are done and 120 remain. With 8 workers: 120 ÷ 8 = 15 days.', '{"1": "Assumes the remaining days are unchanged by the smaller team.", "2": "Gives all 180 worker-days to the 8 workers, forgetting the 5 days already worked.", "3": "Gives the remaining 120 worker-days to the 4 workers who left."}'),
  ('MAT-0304', 'Ratio, rates and proportion', 'Average speed', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A car goes from city X to city Y at 60 km/h and returns along the same road at 40 km/h. What is its average speed for the whole trip?', '["50 km/h", "45 km/h", "52 km/h", "48 km/h"]', 3, 'Take the distance as 120 km each way: times 2 h and 3 h. Average speed = 240 km ÷ 5 h = 48 km/h (= 2 × 60 × 40 ÷ 100).', '{"0": "Averages the speeds; more time is spent at the slower speed.", "1": "Weights the slower speed too heavily.", "2": "Weights the faster speed more heavily, but the car spends less time at it."}'),
  ('MAT-0305', 'Ratio, rates and proportion', 'Speed, distance, time', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A train 200 m long passes completely through a station platform 300 m long in 25 seconds. What is the train''s speed in km/h?', '["28.8 km/h", "43.2 km/h", "20 km/h", "72 km/h"]', 3, 'To clear the platform the front must travel 200 + 300 = 500 m. Speed = 500 ÷ 25 = 20 m/s = 20 × 3.6 = 72 km/h.', '{"0": "Uses only the train''s length (200 m in 25 s = 8 m/s).", "1": "Uses only the platform''s length (300 m in 25 s = 12 m/s).", "2": "Finds 20 m/s but does not convert to km/h."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0306', 'Ratio, rates and proportion', 'Relative speed', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two trains, 150 m and 100 m long, run on parallel tracks in opposite directions at 54 km/h and 36 km/h. How long do they take to pass each other completely?', '["50 seconds", "6 seconds", "10 seconds", "25 seconds"]', 2, 'Relative speed = 54 + 36 = 90 km/h = 25 m/s. Distance to cover = 150 + 100 = 250 m. Time = 250 ÷ 25 = 10 s.', '{"0": "Uses the difference of the speeds (5 m/s); they move in opposite directions.", "1": "Uses only the longer train''s length.", "3": "Uses the total length with only the slower train''s speed (10 m/s)."}'),
  ('MAT-0307', 'Ratio, rates and proportion', 'Relative speed', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A boat travels 30 km downstream in 2 hours and the same 30 km upstream in 3 hours. What is the speed of the current?', '["2.5 km/h", "5 km/h", "12.5 km/h", "15 km/h"]', 0, 'Downstream speed = 15 km/h = boat + current; upstream = 10 km/h = boat − current. Current = (15 − 10) ÷ 2 = 2.5 km/h.', '{"1": "That is the difference of the two speeds, which is twice the current.", "2": "That is the boat''s speed in still water.", "3": "That is the downstream speed."}'),
  ('MAT-0308', 'Ratio, rates and proportion', 'Mixtures', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Tea costing Rs 600 per kg is mixed with tea costing Rs 900 per kg to make a blend worth Rs 700 per kg. In what ratio (cheaper : dearer) are they mixed?', '["1 : 2", "2 : 1", "2 : 3", "1 : 1"]', 1, 'Rs 100 below the blend price on each kg of cheap tea must balance Rs 200 above it on each kg of dear tea. So cheap : dear = 200 : 100 = 2 : 1.', '{"0": "Reverses the ratio; the blend is closer to the cheaper tea, so there is more of it.", "2": "Uses the prices 600 : 900.", "3": "Equal amounts would give a blend of Rs 750 per kg."}'),
  ('MAT-0309', 'Ratio, rates and proportion', 'Concentration and dilution', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A 40-litre mixture contains milk and water in the ratio 5 : 3. How much water must be added to make the ratio 1 : 1?', '["15 litres", "40 litres", "10 litres", "25 litres"]', 2, 'Milk = 25 L, water = 15 L. For 1 : 1, water must equal 25 L, so add 10 L.', '{"0": "That is the water already in the mixture.", "1": "Doubles the mixture, which gives 25 : 55, not 1 : 1.", "3": "That is the milk."}'),
  ('MAT-0310', 'Ratio, rates and proportion', 'Ratio change', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The ages of two sisters are in the ratio 3 : 5. In 6 years'' time the ratio will be 3 : 4. How old is the elder sister now?', '["6 years", "10 years", "15 years", "16 years"]', 1, 'Ages 3k and 5k. (3k + 6)/(5k + 6) = 3/4 gives 12k + 24 = 15k + 18, so k = 2. Ages 6 and 10. The elder is 10.', '{"0": "That is the younger sister''s age.", "2": "Takes k = 3, which gives 9 and 15 now and 15 : 21 later, not 3 : 4.", "3": "That is the elder sister''s age in 6 years."}'),
  ('MAT-0311', 'Ratio, rates and proportion', 'Scale and maps', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A map has a scale of 1 : 250,000. A lake covers 12 cm² on the map. What is its real area?', '["30 km²", "7.5 km²", "750 km²", "75 km²"]', 3, '1 cm on the map is 250,000 cm = 2.5 km. So 1 cm² is 2.5² = 6.25 km². Area = 12 × 6.25 = 75 km².', '{"0": "Scales area by 2.5 (the length factor) instead of 2.5² = 6.25.", "1": "Loses a factor of 10 when converting units.", "2": "Gains a factor of 10 when converting units."}'),
  ('MAT-0312', 'Ratio, rates and proportion', 'Formula substitution', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A drug is given at 15 mg per kg of body mass per day, split into 3 equal doses. How much is each dose for a child of 24 kg?', '["120 mg", "360 mg", "40 mg", "5 mg"]', 0, 'Daily amount = 15 × 24 = 360 mg. Each of 3 doses = 360 ÷ 3 = 120 mg.', '{"1": "That is the total daily amount.", "2": "Divides 120 by 3 again.", "3": "Divides the per-kg rate by 3 and forgets the body mass."}'),
  ('MAT-0313', 'Ratio, rates and proportion', 'Unit rates', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '1.5 litres of fluid is to be given by drip over 12 hours. The drip set delivers 20 drops per mL. About how many drops per minute are needed?', '["42", "125", "2", "2,500"]', 0, 'Total drops = 1,500 mL × 20 = 30,000. Time = 12 × 60 = 720 min. 30,000 ÷ 720 ≈ 41.7, about 42 drops per minute.', '{"1": "That is the rate in mL per hour.", "2": "That is roughly the rate in mL per minute.", "3": "That is the number of drops per hour."}'),
  ('MAT-0314', 'Ratio, rates and proportion', 'Concentration and dilution', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '50 mL of an 8% solution is diluted with water to make a 2% solution. How much water is added?', '["200 mL", "100 mL", "4 mL", "150 mL"]', 3, 'The amount of solute stays the same: 8% × 50 = 4 mL. At 2%, the volume is 4 ÷ 0.02 = 200 mL. Water added = 200 − 50 = 150 mL.', '{"0": "That is the final volume, not the water added.", "1": "Doubles the volume, which would give 4%.", "2": "That is the amount of solute, not the water."}'),
  ('MAT-0315', 'Ratio, rates and proportion', 'Direct proportion', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'y varies directly as x² and inversely as z. When x = 2 and z = 3, y = 12. What is y when x = 4 and z = 6?', '["48", "24", "12", "96"]', 1, 'y = kx²/z. 12 = k × 4/3 gives k = 9. Then y = 9 × 16/6 = 24.', '{"0": "Uses x² but forgets to divide by the larger z.", "2": "Assumes doubling x and z cancel out.", "3": "Multiplies by z instead of dividing."}'),
  ('MAT-0316', 'Ratio, rates and proportion', 'Proportional reasoning', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '3 machines make 180 bolts in 4 hours. Working at the same rate, how many bolts do 5 machines make in 6 hours?', '["300", "270", "450", "1,800"]', 2, 'One machine makes 180 ÷ (3 × 4) = 15 bolts an hour. 5 machines × 6 hours × 15 = 450.', '{"0": "Scales for the machines only.", "1": "Scales for the hours only.", "3": "Multiplies 180 by 5 × 6 ÷ 3 and forgets to divide by the 4 hours."}'),
  ('MAT-0317', 'Ratio, rates and proportion', 'Relative speed', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A cyclist leaves at 40 km/h. Two hours later a car leaves the same place along the same road at 60 km/h. How long after the car starts does it catch the cyclist?', '["2 hours", "6 hours", "4 hours", "1.6 hours"]', 2, 'The cyclist''s head start is 40 × 2 = 80 km. The car closes the gap at 60 − 40 = 20 km/h, so it needs 80 ÷ 20 = 4 hours.', '{"0": "Uses the head start time instead of the head start distance.", "1": "That is how long the cyclist has been riding when caught.", "3": "Divides the 80 km head start by 50 km/h."}'),
  ('MAT-0318', 'Ratio, rates and proportion', 'Speed, distance, time', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If Hina walks to school at 5/4 of her usual speed, she arrives 12 minutes earlier than usual. How long does her usual walk take?', '["48 minutes", "15 minutes", "12 minutes", "60 minutes"]', 3, 'At 5/4 of the speed, the time is 4/5 of the usual time t. The saving is t − 4t/5 = t/5 = 12 min, so t = 60 minutes.', '{"0": "That is the time at the faster speed.", "1": "Uses 12 × 5/4.", "2": "That is the time saved, not the usual time."}'),
  ('MAT-0319', 'Ratio, rates and proportion', 'Inverse proportion', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A hostel has enough food for 120 students for 30 days. After 10 days, 40 more students arrive. How many more days will the remaining food last?', '["20", "15", "22.5", "30"]', 1, 'Food left after 10 days = 120 × 20 = 2,400 student-days. With 160 students: 2,400 ÷ 160 = 15 days.', '{"0": "Ignores the new students.", "2": "Uses 120/160 of 30 days.", "3": "Assumes the food still lasts the full original 30 days."}'),
  ('MAT-0320', 'Ratio, rates and proportion', 'Unit conversion', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Aluminium has a density of 2.7 g/cm³. What is this in kg/m³?', '["2,700 kg/m³", "2.7 kg/m³", "2,700,000 kg/m³", "0.0027 kg/m³"]', 0, '1 m³ = 100³ = 1,000,000 cm³ and 1,000 g = 1 kg. 2.7 g/cm³ × 1,000,000 ÷ 1,000 = 2,700 kg/m³.', '{"1": "Assumes the unit change makes no difference.", "2": "Converts cm³ to m³ but forgets to change grams to kilograms.", "3": "Changes grams to kilograms but forgets that 1 m³ holds a million cm³."}'),
  ('MAT-0321', 'Algebra', 'Writing expressions', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A price p is increased by q percent. Which expression gives the new price?', '["p + q", "p(1 + q/100)", "pq/100", "p(1 + q)"]', 1, 'q percent of p is pq/100. New price = p + pq/100 = p(1 + q/100).', '{"0": "Adds q rupees, not q percent.", "2": "That is only the increase.", "3": "Treats q percent as q whole times the price."}'),
  ('MAT-0322', 'Algebra', 'Writing expressions', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Tap A fills 1/m of a tank per hour and tap B fills 1/n of the tank per hour. What fraction of the tank do they fill together in 3 hours?', '["3/(m + n)", "(m + n)/(mn)", "3/(mn)", "3(m + n)/(mn)"]', 3, 'Together they fill 1/m + 1/n = (m + n)/(mn) per hour. In 3 hours: 3(m + n)/(mn).', '{"0": "Adds the times instead of the rates.", "1": "That is the amount filled in 1 hour.", "2": "Multiplies the rates instead of adding them."}'),
  ('MAT-0323', 'Algebra', 'Writing expressions', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A pen costs x rupees. A notebook costs Rs 15 more than two pens. What is the cost, in rupees, of 3 notebooks and 2 pens?', '["8x + 45", "7x + 45", "5x + 15", "8x + 15"]', 0, 'Notebook = 2x + 15. 3 notebooks = 6x + 45; with 2 pens: 6x + 45 + 2x = 8x + 45.', '{"1": "Adds one pen instead of two.", "2": "Uses one notebook and three pens.", "3": "Forgets to multiply the extra Rs 15 by 3."}'),
  ('MAT-0324', 'Algebra', 'Inequalities', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'a and b are numbers with a > b > 1. Which expression must be greater than 1?', '["b/a", "(b − 1)/(a − 1)", "a/b", "1/(ab)"]', 2, 'Since a > b > 0, dividing gives a/b > 1. Each of the others is a smaller positive number over a larger one, so it is less than 1.', '{"0": "b < a, so b/a is less than 1.", "1": "b − 1 < a − 1, so this is less than 1.", "3": "ab > 1, so 1/(ab) is less than 1."}'),
  ('MAT-0325', 'Algebra', 'Linear equations', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '3p = 5q and 10q = r. Which of these is true?', '["r = 2p", "r = 6p", "r = 50p/3", "r = 3p/5"]', 1, '5q = 3p, so 10q = 6p. Since r = 10q, r = 6p.', '{"0": "Uses 10q = 2 × 5q but forgets the 3 in 3p.", "2": "Uses q = 5p/3, turning 3p = 5q round the wrong way.", "3": "That is q, not r."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0326', 'Algebra', 'Expanding and factorising', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If x + 1/x = 5, what is the value of x² + 1/x²?', '["25", "27", "10", "23"]', 3, '(x + 1/x)² = x² + 2 + 1/x², so x² + 1/x² = 5² − 2 = 23.', '{"0": "Squares 5 but forgets to subtract the 2 from the middle term.", "1": "Adds 2 instead of subtracting it.", "2": "Doubles 5 instead of squaring."}'),
  ('MAT-0327', 'Algebra', 'Expanding and factorising', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If x + 1/x = 3, what is the value of x³ + 1/x³?', '["27", "18", "24", "7"]', 1, '(x + 1/x)³ = x³ + 1/x³ + 3(x + 1/x). So x³ + 1/x³ = 27 − 3 × 3 = 18.', '{"0": "Cubes 3 but forgets to subtract 3(x + 1/x).", "2": "Subtracts 3 instead of 3 × 3.", "3": "That is x² + 1/x²."}'),
  ('MAT-0328', 'Algebra', 'Quadratic equations', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The roots of 2x² − 7x + 3 = 0 are p and q. What is p² + q²?', '["49/4", "43/4", "37/4", "9"]', 2, 'p + q = 7/2 and pq = 3/2. p² + q² = (p + q)² − 2pq = 49/4 − 3 = 37/4. (Check: the roots are 3 and 1/2, and 9 + 1/4 = 37/4.)', '{"0": "That is (p + q)²; it still needs − 2pq.", "1": "Subtracts pq instead of 2pq.", "3": "Squares only the larger root, 3."}'),
  ('MAT-0329', 'Algebra', 'Quadratic equations', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'For which positive value of k does x² − kx + 9 = 0 have two equal roots?', '["6", "3", "9", "36"]', 0, 'Equal roots need the discriminant to be zero: k² − 4 × 1 × 9 = 0, so k² = 36 and k = 6.', '{"1": "Uses k = √9 instead of k² = 4 × 9.", "2": "Sets k equal to the constant term.", "3": "That is k², not k."}'),
  ('MAT-0330', 'Algebra', 'Inequalities', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many integers x satisfy |2x − 3| ≤ 7?', '["8", "7", "15", "6"]', 0, '−7 ≤ 2x − 3 ≤ 7, so −4 ≤ 2x ≤ 10 and −2 ≤ x ≤ 5. Integers −2 to 5: eight of them.', '{"1": "Leaves out one end point; the inequality includes equality.", "2": "Counts the integers from −7 to 7.", "3": "Leaves out both end points −2 and 5."}'),
  ('MAT-0331', 'Algebra', 'Functions', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'f(x) = 2x + 3 and g(x) = x² − 1. What is f(g(3))?', '["80", "8", "19", "72"]', 2, 'g(3) = 9 − 1 = 8. f(8) = 2 × 8 + 3 = 19.', '{"0": "That is g(f(3)) = 9² − 1.", "1": "That is g(3) only.", "3": "Multiplies f(3) × g(3) = 9 × 8."}'),
  ('MAT-0332', 'Algebra', 'Functions', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'f(x) = (3x − 2)/5. What is f⁻¹(4), the value of x for which f(x) = 4?', '["2", "6", "14/3", "22/3"]', 3, 'Solve (3x − 2)/5 = 4: 3x − 2 = 20, 3x = 22, x = 22/3.', '{"0": "That is f(4), not f⁻¹(4).", "1": "Solves 3x − 2 = 4 × 4 instead of 4 × 5.", "2": "Solves 3x = 20 − 6 instead of 20 + 2."}'),
  ('MAT-0333', 'Algebra', 'Logarithms', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Work out log₂ 8 + log₃ (1/9) + log₁₀ 0.001.', '["8", "−2", "2", "−4"]', 1, 'log₂ 8 = 3, log₃ (1/9) = −2 and log₁₀ 0.001 = −3. Total = 3 − 2 − 3 = −2.', '{"0": "Treats all the logarithms as positive (3 + 2 + 3).", "2": "Takes log₃(1/9) as +2 instead of −2.", "3": "Takes log₂ 8 as 1."}'),
  ('MAT-0334', 'Algebra', 'Indices', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If 2ˣ⁺¹ + 2ˣ = 48, what is x?', '["5", "4", "3", "16"]', 1, '2ˣ⁺¹ + 2ˣ = 2 × 2ˣ + 2ˣ = 3 × 2ˣ = 48, so 2ˣ = 16 and x = 4.', '{"0": "That is x + 1, the power in 2ˣ⁺¹ = 32.", "2": "Treats 2 × 2ˣ + 2ˣ as 6 × 2ˣ, so 2ˣ = 8.", "3": "That is 2ˣ, not x."}'),
  ('MAT-0335', 'Algebra', 'Simultaneous equations', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '3x + 2y = 12 and 5x − 3y = 1. What is xy?', '["6", "5", "−1", "3"]', 0, 'Multiply the first by 3 and the second by 2: 9x + 6y = 36 and 10x − 6y = 2. Adding, 19x = 38, x = 2; then y = 3. xy = 6.', '{"1": "That is x + y.", "2": "That is x − y.", "3": "That is y alone."}'),
  ('MAT-0336', 'Algebra', 'Inequalities', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Which describes all the solutions of x² − 5x + 6 < 0?', '["x < 2 or x > 3", "x < 2", "2 < x < 3", "−3 < x < −2"]', 2, 'x² − 5x + 6 = (x − 2)(x − 3), which is negative only between the roots: 2 < x < 3.', '{"0": "That is where x² − 5x + 6 > 0.", "1": "Only one side of the solution; for x < 2 the expression is positive.", "3": "Uses the wrong signs for the roots."}'),
  ('MAT-0337', 'Algebra', 'Word problems', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The digits of a two-digit number add up to 9. When the digits are reversed, the number increases by 27. What is the number?', '["63", "45", "27", "36"]', 3, 'Number 10a + b with a + b = 9. Reversed minus original = 9(b − a) = 27, so b − a = 3. Then a = 3, b = 6: the number is 36.', '{"0": "That is the reversed number.", "1": "Digits add to 9, but reversing adds only 9.", "2": "That is the increase, not the number."}'),
  ('MAT-0338', 'Algebra', 'Expanding and factorising', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '(x − 2) is a factor of x³ + kx² − 4x + 8. What is k?', '["2", "−4", "0", "−2"]', 3, 'By the factor theorem, the expression is 0 at x = 2: 8 + 4k − 8 + 8 = 0, so 4k = −8 and k = −2.', '{"0": "Gets the sign wrong when solving 4k + 8 = 0.", "1": "Leaves out the −4x term when substituting.", "2": "Assumes the x² term is absent."}'),
  ('MAT-0339', 'Algebra', 'Expanding and factorising', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the remainder when x³ − 2x² + 5 is divided by (x + 1)?', '["2", "4", "8", "5"]', 0, 'By the remainder theorem, substitute x = −1: −1 − 2 + 5 = 2.', '{"1": "Substitutes x = 1 instead of x = −1.", "2": "Takes (−1)³ as +1 and (−1)² as −1.", "3": "Takes only the constant term."}'),
  ('MAT-0340', 'Algebra', 'Indices', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Simplify 27^(2/3) × 16^(−3/4).', '["72", "8/9", "9/8", "3/2"]', 2, '27^(2/3) = (∛27)² = 9. 16^(−3/4) = 1/(⁴√16)³ = 1/8. Product = 9/8.', '{"0": "Ignores the negative sign in the second power (9 × 8).", "1": "Turns the whole answer upside down.", "3": "Uses 27^(1/3) × 16^(−1/4) only."}'),
  ('MAT-0341', 'Algebra', 'Algebraic fractions', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'a/b = 3/4. What is (2a + b)/(a − 2b)?', '["2", "−2", "−10", "10"]', 1, 'Take a = 3, b = 4 (any multiple gives the same value). 2a + b = 10 and a − 2b = −5, so the ratio is −2.', '{"0": "Gets the sign of a − 2b wrong.", "2": "Uses a − b = −1 instead of a − 2b in the denominator.", "3": "Forgets to divide by a − 2b."}'),
  ('MAT-0342', 'Algebra', 'Straight-line graphs', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A line passes through (2, 5) and is perpendicular to y = 2x + 1. Where does it cross the y-axis?', '["(0, 6)", "(0, 1)", "(0, 4)", "(0, 9)"]', 0, 'Perpendicular gradient = −1/2. y = −x/2 + c through (2, 5): 5 = −1 + c, c = 6. It crosses the y-axis at (0, 6).', '{"1": "Uses gradient 2, the same as the given line.", "2": "Uses gradient +1/2 instead of −1/2.", "3": "Uses gradient −2 (the negative, not the negative reciprocal)."}'),
  ('MAT-0343', 'Algebra', 'Expanding and factorising', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'a + b = 7 and ab = 10, with a > b. What is a − b?', '["29", "9", "√69", "3"]', 3, '(a − b)² = (a + b)² − 4ab = 49 − 40 = 9, so a − b = 3 (positive because a > b). The numbers are 5 and 2.', '{"0": "That is a² + b².", "1": "That is (a − b)², not a − b.", "2": "Uses (a − b)² = 49 + 20 instead of 49 − 40."}'),
  ('MAT-0344', 'Algebra', 'Changing the subject', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The period of a pendulum is T = 2π√(L/g). Which formula gives L?', '["L = gT/(2π)", "L = gT²/(4π²)", "L = 4π²g/T²", "L = gT²/(2π)"]', 1, 'Divide by 2π: T/(2π) = √(L/g). Square: T²/(4π²) = L/g. Multiply by g: L = gT²/(4π²).', '{"0": "Forgets to square both sides to remove the square root.", "2": "Inverts the formula.", "3": "Squares T but not the 2π."}'),
  ('MAT-0345', 'Algebra', 'Indices', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'If 9ˣ = 27ˣ⁻¹, what is x?', '["1", "−3", "3", "3/5"]', 2, '9ˣ = 3²ˣ and 27ˣ⁻¹ = 3³⁽ˣ⁻¹⁾. So 2x = 3x − 3, giving x = 3.', '{"0": "Sets 2x = 3x − 1, forgetting to multiply the −1 by 3.", "1": "Gets the sign wrong when solving 2x = 3x − 3.", "3": "Adds the exponents instead of equating them."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0346', 'Algebra', 'Word problems', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A father is 4 times as old as his son. In 20 years, he will be twice as old as his son. How old is the son now?', '["40", "20", "30", "10"]', 3, 'Son s, father 4s. In 20 years: 4s + 20 = 2(s + 20), so 2s = 20 and s = 10.', '{"0": "That is the father''s age.", "1": "Assumes the son''s age equals the number of years.", "2": "That is the son''s age in 20 years."}'),
  ('MAT-0347', 'Geometry and measurement', 'Angles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the smaller angle between the hands of a clock at 7:20?', '["90°", "110°", "260°", "100°"]', 3, 'Minute hand: 20 × 6° = 120°. Hour hand: 7 × 30° + 20 × 0.5° = 220°. Difference = 100°.', '{"0": "Leaves the hour hand exactly on 7; by 7:20 it has moved 10°.", "1": "Moves the hour hand back instead of forward.", "2": "That is the larger (reflex) angle."}'),
  ('MAT-0348', 'Geometry and measurement', 'Transformations', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The point (3, −5) is reflected in the y-axis. Where is its image?', '["(3, 5)", "(−3, 5)", "(−3, −5)", "(−5, 3)"]', 2, 'Reflecting in the y-axis changes the sign of the x-coordinate only: (3, −5) → (−3, −5).', '{"0": "That is a reflection in the x-axis.", "1": "That is a rotation of 180° about the origin.", "3": "Swaps the coordinates and changes a sign."}'),
  ('MAT-0349', 'Geometry and measurement', 'Transformations', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The point (2, 7) is reflected in the line y = x. Where is its image?', '["(−2, 7)", "(7, 2)", "(−7, −2)", "(2, −7)"]', 1, 'Reflecting in y = x swaps the coordinates: (2, 7) → (7, 2).', '{"0": "That is a reflection in the y-axis.", "2": "That is a reflection in the line y = −x.", "3": "That is a reflection in the x-axis."}'),
  ('MAT-0350', 'Geometry and measurement', 'Transformations', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The point (−4, 6) is moved 5 units to the right and 3 units down. Where does it end up?', '["(−9, 9)", "(1, 9)", "(−1, 3)", "(1, 3)"]', 3, 'Right 5: x = −4 + 5 = 1. Down 3: y = 6 − 3 = 3. New point (1, 3).', '{"0": "Moves left and up instead.", "1": "Moves up instead of down.", "2": "Moves right by 3 instead of 5."}'),
  ('MAT-0351', 'Geometry and measurement', 'Transformations', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The point (4, 1) is rotated 90° anticlockwise about the origin. Where is its image?', '["(−1, 4)", "(1, −4)", "(−4, −1)", "(−4, 1)"]', 0, 'A 90° anticlockwise rotation about the origin sends (x, y) to (−y, x): (4, 1) → (−1, 4).', '{"1": "That is a 90° clockwise rotation.", "2": "That is a 180° rotation.", "3": "That is a reflection in the y-axis."}'),
  ('MAT-0352', 'Geometry and measurement', 'Coordinate geometry', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Point A is 3 units to the left of point B and 2 units above it. B is at (5, −1). What are the coordinates of A?', '["(8, 1)", "(2, −3)", "(2, 1)", "(3, 2)"]', 2, 'Left 3: x = 5 − 3 = 2. Up 2: y = −1 + 2 = 1. A = (2, 1).', '{"0": "Moves right instead of left.", "1": "Moves down instead of up.", "3": "Gives the movement, not the point."}'),
  ('MAT-0353', 'Geometry and measurement', 'Triangles', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two sides of a triangle are 4 cm and 9 cm. Which of these could be the length of the third side?', '["5 cm", "13 cm", "6 cm", "14 cm"]', 2, 'The third side must be more than 9 − 4 = 5 and less than 9 + 4 = 13. Only 6 cm fits.', '{"0": "4 + 5 = 9 makes a flat line, not a triangle.", "1": "4 + 9 = 13 makes a flat line, not a triangle.", "3": "14 is longer than 4 + 9."}'),
  ('MAT-0354', 'Geometry and measurement', 'Triangles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two sides of a triangle are 6 cm and 10 cm. The third side is a whole number of centimetres. How many different lengths are possible for it?', '["11", "10", "13", "16"]', 0, 'The third side must be more than 10 − 6 = 4 and less than 10 + 6 = 16: lengths 5, 6, …, 15. That is 11 lengths.', '{"1": "Leaves out one end, counting 5 to 14 or 6 to 15.", "2": "Includes the end values 4 and 16, which give flat shapes.", "3": "Counts every length from 1 to 16."}'),
  ('MAT-0355', 'Geometry and measurement', 'Packing', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many solid cubes of edge 2 cm can be packed into a box that measures 11 cm × 8 cm × 6 cm inside?', '["66", "528", "264", "60"]', 3, 'Along each edge: 11 ÷ 2 → 5 whole cubes, 8 ÷ 2 = 4, 6 ÷ 2 = 3. Total = 5 × 4 × 3 = 60.', '{"0": "Divides the volumes (528 ÷ 8), but 11 cm holds only 5 whole cubes, not 5.5.", "1": "That is the volume of the box in cm³.", "2": "Divides the box volume by 2 instead of by the cube''s volume 8."}'),
  ('MAT-0356', 'Geometry and measurement', 'Packing', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A floor 3.6 m by 2.4 m is covered with square tiles of side 30 cm. How many tiles are needed?', '["8.64", "96", "864", "12"]', 1, 'Along 3.6 m: 360 ÷ 30 = 12 tiles. Along 2.4 m: 240 ÷ 30 = 8 tiles. 12 × 8 = 96 tiles.', '{"0": "That is the floor area in m², not the number of tiles.", "2": "Divides the floor area, 86,400 cm², by 100 instead of by one tile''s area, 900 cm².", "3": "That is only the tiles along one 3.6 m edge."}'),
  ('MAT-0357', 'Geometry and measurement', 'Packing', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'An exam hall is 20 m long and 12 m wide. Each desk needs a rectangle 2 m long (along the hall''s length) and 1.5 m wide. What is the greatest number of desks that fit in this arrangement?', '["78", "240", "60", "80"]', 3, 'Along 20 m: 20 ÷ 2 = 10 desks. Across 12 m: 12 ÷ 1.5 = 8 rows. 10 × 8 = 80 desks.', '{"0": "Turns the desks the other way (13 × 6).", "1": "Gives each desk only 1 m².", "2": "Uses 2 m in both directions."}'),
  ('MAT-0358', 'Geometry and measurement', 'Perimeter', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A square garden has an area of 196 m². How long is a fence that goes all the way round it?', '["14 m", "56 m", "49 m", "784 m"]', 1, 'Side = √196 = 14 m. Perimeter = 4 × 14 = 56 m.', '{"0": "That is one side only.", "2": "Divides the area by 4.", "3": "Multiplies the area by 4."}'),
  ('MAT-0359', 'Geometry and measurement', 'Similarity and scale', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The edges of two cubes are in the ratio 2 : 3. What is the ratio of their surface areas?', '["4 : 9", "2 : 3", "8 : 27", "6 : 9"]', 0, 'Areas scale with the square of lengths: 2² : 3² = 4 : 9.', '{"1": "That is the ratio of the edges.", "2": "That is the ratio of the volumes.", "3": "Multiplies only the first part by 3."}'),
  ('MAT-0360', 'Geometry and measurement', 'Similarity and scale', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A jar holds 400 mL. A larger jar has exactly the same shape, but every length is 1.5 times as long. How much does the larger jar hold?', '["600 mL", "900 mL", "1,350 mL", "3,375 mL"]', 2, 'Volume scales with the cube of the length factor: 1.5³ = 3.375. 400 × 3.375 = 1,350 mL.', '{"0": "Scales the capacity by 1.5 (the length factor).", "1": "Scales by 1.5² (the area factor).", "3": "Uses the right factor 1.5³ but on 1,000 mL instead of 400 mL."}'),
  ('MAT-0361', 'Geometry and measurement', 'Similarity and scale', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A cube has a surface area of 96 cm². Each edge is then halved. What is the new surface area?', '["24 cm²", "48 cm²", "12 cm²", "8 cm²"]', 0, 'Halving every length multiplies area by (1/2)² = 1/4. 96 ÷ 4 = 24 cm².', '{"1": "Halves the area instead of quartering it.", "2": "Divides by 8, the volume factor.", "3": "That is the new volume in cm³, not the area."}'),
  ('MAT-0362', 'Geometry and measurement', 'Angles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Each interior angle of a regular polygon is 150°. How many sides does it have?', '["10", "12", "15", "6"]', 1, 'Each exterior angle is 180° − 150° = 30°. Exterior angles add to 360°, so there are 360 ÷ 30 = 12 sides.', '{"0": "That gives interior angles of 144°.", "2": "That gives interior angles of 156°.", "3": "A hexagon''s interior angles are 120°."}'),
  ('MAT-0363', 'Geometry and measurement', 'Polygons', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many diagonals does a 10-sided polygon (decagon) have?', '["35", "45", "70", "20"]', 0, 'Each vertex joins to 10 − 3 = 7 others by a diagonal; 10 × 7 counts every diagonal twice. 70 ÷ 2 = 35.', '{"1": "That counts every pair of vertices, including the 10 sides.", "2": "Counts each diagonal twice (10 × 7).", "3": "Uses 2 diagonals per vertex."}'),
  ('MAT-0364', 'Geometry and measurement', 'Volume and surface area', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A cube has a total surface area of 150 cm². What is its volume?', '["25 cm³", "216 cm³", "125 cm³", "625 cm³"]', 2, 'One face = 150 ÷ 6 = 25 cm², so the edge is 5 cm and the volume is 5³ = 125 cm³.', '{"0": "25 cm² is the area of one face, not a volume.", "1": "Takes the edge as 6 cm.", "3": "Squares the face area (25²) instead of cubing the edge."}'),
  ('MAT-0365', 'Geometry and measurement', 'Volume and surface area', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A sphere just fits inside a cube of edge 6 cm. What is the volume of the sphere?', '["288π cm³", "216 cm³", "27π cm³", "36π cm³"]', 3, 'The sphere''s diameter is the cube''s edge, so r = 3 cm. V = (4/3)πr³ = (4/3)π × 27 = 36π cm³.', '{"0": "Uses radius 6 instead of 3.", "1": "That is the volume of the cube.", "2": "Uses πr³ without the 4/3."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0366', 'Geometry and measurement', 'Volume and surface area', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A cone has base radius 3 cm and vertical height 4 cm. What is its curved surface area?', '["15π cm²", "12π cm²", "24π cm²", "12π cm³"]', 0, 'Slant height l = √(3² + 4²) = 5 cm. Curved surface area = πrl = π × 3 × 5 = 15π cm².', '{"1": "Uses the vertical height instead of the slant height.", "2": "That is the total surface area, including the base.", "3": "That is the volume, (1/3)π × 9 × 4."}'),
  ('MAT-0367', 'Geometry and measurement', 'Volume and surface area', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The radius of a cylinder is halved and its height is doubled. What happens to its volume?', '["It stays the same", "It is halved", "It is doubled", "It is quartered"]', 1, 'V = πr²h. New V = π(r/2)²(2h) = πr²h × (1/4) × 2 = half the old volume.', '{"0": "Assumes halving and doubling cancel, but the radius is squared.", "2": "Applies the height change only.", "3": "Applies the radius change only."}'),
  ('MAT-0368', 'Geometry and measurement', 'Pythagoras', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A right-angled triangle has shorter sides 9 cm and 12 cm. What is the length of the altitude from the right angle to the hypotenuse?', '["15 cm", "10.5 cm", "7.2 cm", "54 cm"]', 2, 'Hypotenuse = 15 cm. Area = ½ × 9 × 12 = 54 cm² = ½ × 15 × h, so h = 108 ÷ 15 = 7.2 cm.', '{"0": "That is the hypotenuse.", "1": "Averages 9 and 12.", "3": "That is the area in cm², not a length."}'),
  ('MAT-0369', 'Geometry and measurement', 'Circles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A sector of a circle of radius 10 cm has an angle of 72° at the centre. What is its area?', '["4π cm²", "100π cm²", "20π cm²", "40π cm²"]', 2, 'The sector is 72/360 = 1/5 of the circle. Area = (1/5) × π × 10² = 20π cm².', '{"0": "That is the arc length (in cm), not the area.", "1": "That is the area of the whole circle.", "3": "Uses 72/180 instead of 72/360."}'),
  ('MAT-0370', 'Geometry and measurement', 'Coordinate geometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the distance between the points (−2, 3) and (4, −5)?', '["14", "10", "2√5", "√20"]', 1, 'Differences: 4 − (−2) = 6 and −5 − 3 = −8. Distance = √(36 + 64) = √100 = 10.', '{"0": "Adds the differences 6 + 8 instead of using Pythagoras.", "2": "Uses the sums (2, −2) instead of the differences.", "3": "Uses differences 2 and 4."}'),
  ('MAT-0371', 'Geometry and measurement', 'Coordinate geometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the area of the triangle with vertices (1, 2), (5, 6) and (7, 1)?', '["14", "28", "22", "16"]', 0, 'Shoelace: ½|1(6 − 1) + 5(1 − 2) + 7(2 − 6)| = ½|5 − 5 − 28| = 14.', '{"1": "Forgets to halve the shoelace total.", "2": "Takes only the largest corner triangle (8) from the 6 × 5 surrounding box.", "3": "That is the total of the three corner triangles, not the triangle itself."}'),
  ('MAT-0372', 'Geometry and measurement', 'Circles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A chord 16 cm long is drawn in a circle of radius 10 cm. How far is the chord from the centre?', '["8 cm", "2 cm", "√156 cm", "6 cm"]', 3, 'The perpendicular from the centre bisects the chord: half-chord 8 cm. Distance = √(10² − 8²) = √36 = 6 cm.', '{"0": "That is half the chord.", "1": "Subtracts 8 from 10.", "2": "Uses √(16² − 10²), treating the whole chord as the hypotenuse."}'),
  ('MAT-0373', 'Geometry and measurement', 'Similarity and scale', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two similar triangles have areas in the ratio 9 : 25. The smaller has a perimeter of 18 cm. What is the perimeter of the larger?', '["50 cm", "34 cm", "30 cm", "10.8 cm"]', 2, 'The length ratio is √9 : √25 = 3 : 5. Perimeter = 18 × 5/3 = 30 cm.', '{"0": "Scales the perimeter by the area ratio 25/9.", "1": "Adds 25 − 9 = 16 cm.", "3": "Scales down instead of up."}'),
  ('MAT-0374', 'Geometry and measurement', 'Area', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A rectangle has a diagonal of 13 cm and a perimeter of 34 cm. What is its area?', '["120 cm²", "60 cm²", "72.25 cm²", "169 cm²"]', 1, 'l + w = 17 and l² + w² = 169. (l + w)² = 289 = 169 + 2lw, so lw = 60 cm². (The sides are 12 and 5.)', '{"0": "That is 2lw, not lw.", "2": "Assumes a square of side 8.5 cm.", "3": "That is the square of the diagonal."}'),
  ('MAT-0375', 'Geometry and measurement', 'Area', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the area of an equilateral triangle with side 6 cm?', '["18 cm²", "18√3 cm²", "36 cm²", "9√3 cm²"]', 3, 'Height = √(6² − 3²) = √27 = 3√3. Area = ½ × 6 × 3√3 = 9√3 cm² (= (√3/4) × 36).', '{"0": "Uses ½ × 6 × 6 as if the height were 6.", "1": "Forgets the ½ in ½ × base × height.", "2": "That is the area of a square of side 6."}'),
  ('MAT-0376', 'Geometry and measurement', 'Circles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A circle just fits inside a square of side 10 cm. What is the area of the square outside the circle?', '["(100 − 25π) cm²", "(100 − 100π) cm²", "(100 − 10π) cm²", "(40 − 10π) cm²"]', 0, 'The radius is 5 cm, so the circle''s area is 25π. Area outside = 100 − 25π ≈ 21.5 cm².', '{"1": "Uses radius 10 instead of 5; that would be negative.", "2": "Subtracts the circumference instead of the area.", "3": "Subtracts the circumference from the perimeter."}'),
  ('MAT-0377', 'Geometry and measurement', 'Trigonometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'θ is an acute angle with sin θ = 3/5. What is tan θ?', '["3/4", "4/3", "4/5", "5/3"]', 0, 'Opposite 3, hypotenuse 5, so adjacent = 4. tan θ = opposite ÷ adjacent = 3/4.', '{"1": "That is cot θ (adjacent ÷ opposite).", "2": "That is cos θ.", "3": "That is 1/sin θ."}'),
  ('MAT-0378', 'Geometry and measurement', 'Pythagoras', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A 10 m ladder leans against a wall with its foot 6 m from the wall. The foot slides 2 m further from the wall. How far does the top slide down the wall?', '["8 m", "2 m", "6 m", "1 m"]', 1, 'At first the top is √(100 − 36) = 8 m up. After the foot moves to 8 m, the top is √(100 − 64) = 6 m up. It slides down 8 − 6 = 2 m.', '{"0": "That is the original height on the wall.", "2": "That is the new height on the wall.", "3": "Halves the 2 m movement of the foot."}'),
  ('MAT-0379', 'Geometry and measurement', 'Angles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The angles of a triangle are in the ratio 2 : 3 : 4. What is the largest angle?', '["90°", "40°", "120°", "80°"]', 3, '9 parts make 180°, so one part is 20°. The largest is 4 × 20° = 80°.', '{"0": "Assumes the largest angle is a right angle.", "1": "That is the smallest angle.", "2": "Uses a total of 270° for the three angles."}'),
  ('MAT-0380', 'Geometry and measurement', 'Volume and surface area', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Water fills a cylinder of radius 6 cm to a height of 10 cm. It is all poured into an empty cylinder of radius 4 cm. How high does the water rise?', '["15 cm", "6.67 cm", "22.5 cm", "4.44 cm"]', 2, 'Volume = π × 36 × 10 = 360π. In the narrower cylinder: π × 16 × h = 360π, so h = 22.5 cm.', '{"0": "Scales by the radius ratio 6/4 instead of its square.", "1": "Uses the inverse ratio of the radii.", "3": "Scales the height down instead of up."}'),
  ('MAT-0381', 'Geometry and measurement', 'Angles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the smaller angle between the hour hand and the minute hand of a clock at 3:40?', '["120°", "110°", "130°", "230°"]', 2, 'Minute hand: 40 × 6° = 240°. Hour hand: 3 × 30° + 40 × 0.5° = 110°. Difference = 130°.', '{"0": "Leaves the hour hand at exactly 3 (it has moved on 20° by 3:40).", "1": "Moves the hour hand 1° per minute instead of 0.5°.", "3": "That is the larger (reflex) angle."}'),
  ('MAT-0382', 'Data interpretation and statistics', 'Frequency tables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The table shows the marks (out of 10) of 20 students.
Marks:      5  6  7  8  9
Students:   3  5  7  4  1
What is the mean mark?', '["7", "27", "4", "6.75"]', 3, 'Total = 5×3 + 6×5 + 7×7 + 8×4 + 9×1 = 15 + 30 + 49 + 32 + 9 = 135. Mean = 135 ÷ 20 = 6.75.', '{"0": "That is the mode (and the median), not the mean.", "1": "Divides the total 135 by 5 (the number of columns) instead of 20.", "2": "That is the mean of the frequencies."}'),
  ('MAT-0383', 'Data interpretation and statistics', 'Frequency tables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '24 students were asked how many siblings they have.
Number of siblings:  0  1  2  3  4
Number of students:  4  7  6  5  2
What is the median number of siblings?', '["1", "2", "5", "1.75"]', 1, 'With 24 values, the median is the mean of the 12th and 13th. Cumulative counts: 4 (0 siblings), 11 (up to 1), 17 (up to 2). The 12th and 13th are both 2.', '{"0": "That is the mode (the value with the highest frequency).", "2": "That is the median of the frequency column, not of the data.", "3": "That is the mean."}'),
  ('MAT-0384', 'Data interpretation and statistics', 'Box plots and quartiles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'For the data 3, 5, 7, 8, 10, 12, 15, 18, 20, 22, 25, what is the interquartile range? (Find the quartiles as the medians of the lower and upper halves, leaving out the overall median.)', '["13", "22", "12", "10"]', 0, 'Median = 12 (6th value). Lower half 3, 5, 7, 8, 10 has median Q1 = 7; upper half 15, 18, 20, 22, 25 has median Q3 = 20. IQR = 20 − 7 = 13.', '{"1": "That is the range.", "2": "That is the median.", "3": "Uses 8 and 18 as the quartiles."}'),
  ('MAT-0385', 'Data interpretation and statistics', 'Range and spread', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Each of these data sets has a mean of 10. Which has the largest standard deviation?', '["P: 10, 10, 10, 10", "R: 1, 10, 10, 19", "Q: 8, 9, 11, 12", "S: 5, 10, 10, 15"]', 1, 'Standard deviation measures typical distance from the mean. R has values 9 away from the mean on both sides, more than any other set.', '{"0": "Every value equals the mean, so its standard deviation is 0.", "2": "Its values are all within 2 of the mean.", "3": "Its extreme values are only 5 from the mean; R''s are 9 away."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0386', 'Data interpretation and statistics', 'Effect of changes on averages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The mean of 10 numbers is 15. Two more numbers, 20 and x, are added and the mean of all 12 becomes 16. What is x?', '["16", "42", "12", "22"]', 3, 'Old total = 150. New total = 12 × 16 = 192. The two new numbers add to 42, so x = 42 − 20 = 22.', '{"0": "Assumes x equals the new mean.", "1": "That is 20 + x, the total of both new numbers.", "2": "Makes the two new numbers average 16 (20 + 12 = 32)."}'),
  ('MAT-0387', 'Data interpretation and statistics', 'Mean, median and mode', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Five positive whole numbers have a mean of 6, a median of 5 and a single mode of 3. What is the largest possible value of the biggest number?', '["14", "19", "13", "12"]', 2, 'Mean 6 → total 30. Sorted: 3, 3, 5, a, b with a > 5 (a = 5 would make 5 a second mode) and a ≠ b. To make b largest, take a = 6: b = 30 − 3 − 3 − 5 − 6 = 13.', '{"0": "Lets the fourth number be 5; then 3 and 5 would both be modes.", "1": "Uses 3, 3, 5 and leaves 30 − 11 for one number, forgetting the fourth.", "3": "Makes the fourth number 7 instead of the smallest allowed, 6."}'),
  ('MAT-0388', 'Data interpretation and statistics', 'Pie charts', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A family''s monthly income of Rs 80,000 is shown in a pie chart. The food sector has an angle of 126° and the rent sector 90°. How much more is spent on food than on rent?', '["Rs 8,000", "Rs 28,000", "Rs 20,000", "Rs 36,000"]', 0, 'Each degree is 80,000 ÷ 360 of the income. The difference of 126° − 90° = 36° is 36/360 = 1/10 of Rs 80,000 = Rs 8,000.', '{"1": "That is the food spending itself.", "2": "That is the rent.", "3": "Treats each degree as Rs 1,000."}'),
  ('MAT-0389', 'Data interpretation and statistics', 'Tables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A shop''s yearly sales (in thousands of rupees) were:
2020: 200   2021: 250   2022: 300   2023: 240   2024: 288
In which year-to-year period was the percentage increase in sales largest?', '["2021 to 2022", "2023 to 2024", "2020 to 2021", "2022 to 2023"]', 2, 'Changes: +50 on 200 = 25%; +50 on 250 = 20%; −60 on 300 = −20%; +48 on 240 = 20%. The largest increase is 25%, from 2020 to 2021.', '{"0": "The rise is the same 50 thousand, but on a larger base it is only 20%.", "1": "The rise of 48 on 240 is 20%.", "3": "Sales fell in that period."}'),
  ('MAT-0390', 'Data interpretation and statistics', 'Box plots and quartiles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A box plot of the scores of 40 students shows: minimum 12, lower quartile 20, median 28, upper quartile 34, maximum 50. About how many students scored between 20 and 34?', '["20", "10", "30", "14"]', 0, 'The box runs from the lower to the upper quartile, so it holds the middle half of the data: about 50% of 40 = 20 students.', '{"1": "That is a quarter of the students.", "2": "That is three quarters of the students.", "3": "That is the interquartile range (34 − 20), a score difference, not a number of students."}'),
  ('MAT-0391', 'Data interpretation and statistics', 'Box plots and quartiles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'For a data set, the lower quartile is 20 and the upper quartile is 34. A value is an outlier if it is more than 1.5 × IQR above the upper quartile or below the lower quartile. Which of these values is an outlier?', '["54", "56", "50", "0"]', 1, 'IQR = 34 − 20 = 14. Limits: 20 − 21 = −1 and 34 + 21 = 55. Only 56 lies outside them.', '{"0": "The upper limit is 34 + 1.5 × 14 = 55, and 54 is below it.", "2": "50 is below the upper limit of 55.", "3": "The lower limit is 20 − 21 = −1, and 0 is above it."}'),
  ('MAT-0392', 'Data interpretation and statistics', 'Cumulative frequency', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The cumulative frequency table shows the heights of 80 students.
Height (cm):        < 150  < 160  < 170  < 180  < 190
Cumulative number:      8     26     52     70     80
How many students are at least 160 cm but less than 180 cm tall?', '["52", "70", "18", "44"]', 3, 'Cumulative counts: 70 are under 180 cm and 26 are under 160 cm. Between: 70 − 26 = 44.', '{"0": "That is the number shorter than 170 cm.", "1": "That is the number shorter than 180 cm.", "2": "That is only the 150–160 cm group."}'),
  ('MAT-0393', 'Data interpretation and statistics', 'Cumulative frequency', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Using the same table of 80 students'' heights:
Height (cm):        < 150  < 160  < 170  < 180  < 190
Cumulative number:      8     26     52     70     80
In which class does the median height lie?', '["150–160 cm", "170–180 cm", "180–190 cm", "160–170 cm"]', 3, 'The median is about the 40th value. 26 are below 160 cm and 52 below 170 cm, so the 40th lies in 160–170 cm.', '{"0": "Only 26 students are below 160 cm, fewer than half of 80.", "1": "52 students (more than half) are already below 170 cm.", "2": "That is the top class."}'),
  ('MAT-0394', 'Data interpretation and statistics', 'Frequency tables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The table shows how long 20 students took to finish a task.
Time (min):   0–10  10–20  20–30  30–40
Students:       4      6      8      2
Using class midpoints, what is the estimated mean time?', '["20 min", "25 min", "19 min", "95 min"]', 2, 'Midpoints 5, 15, 25, 35. Total ≈ 5×4 + 15×6 + 25×8 + 35×2 = 20 + 90 + 200 + 70 = 380. Mean ≈ 380 ÷ 20 = 19 min.', '{"0": "That is the mean of the four midpoints, ignoring the frequencies.", "1": "That is the midpoint of the modal class.", "3": "Divides the total 380 by 4 classes instead of 20 students."}'),
  ('MAT-0395', 'Data interpretation and statistics', 'Mean, median and mode', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A course grade is worked out as 20% of the quiz mark, 30% of the midterm mark and 50% of the final exam mark. Sana scored 80 in quizzes and 70 in the midterm. What must she score in the final to get an overall 75?', '["76", "75", "74", "38"]', 0, '0.2 × 80 + 0.3 × 70 + 0.5x = 75 gives 16 + 21 + 0.5x = 75, so 0.5x = 38 and x = 76.', '{"1": "Assumes the final must equal the target (or uses equal weights).", "2": "Swaps the quiz and midterm weights (0.3 × 80 + 0.2 × 70 = 38, so 0.5x = 37).", "3": "That is 0.5x; it still has to be doubled."}'),
  ('MAT-0396', 'Data interpretation and statistics', 'Range and spread', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The data 7, 12, x, 15, 9 has a range of 10. What are the possible values of x?', '["17 only", "5 or 17", "5 only", "3 or 17"]', 1, 'Without x the values run from 7 to 15 (range 8). For a range of 10, x must extend one end: x = 17 (17 − 7) or x = 5 (15 − 5).', '{"0": "x could also be the smallest value: 15 − 5 = 10.", "2": "x could also be the largest value: 17 − 7 = 10.", "3": "If x = 3, the range is 15 − 3 = 12."}'),
  ('MAT-0397', 'Data interpretation and statistics', 'Mean, median and mode', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Set X is 2, 4, 6, 8, 10 and set Y is 1, 3, 5, 15, 17, 19, 21. The two sets are combined into one list of 12 numbers. What is the median of the combined list?', '["7", "10.5", "6", "8"]', 0, 'Combined and sorted: 1, 2, 3, 4, 5, 6, 8, 10, 15, 17, 19, 21. The 6th and 7th values are 6 and 8, so the median is 7.', '{"1": "Averages the two medians (6 and 15); medians do not combine like that.", "2": "That is the median of set X.", "3": "Takes the 7th value only; with 12 values the median is the mean of the 6th and 7th."}'),
  ('MAT-0398', 'Data interpretation and statistics', 'Effect of changes on averages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The mean of 10 readings was worked out as 50. Later it was found that one reading of 95 had been copied as 59. What is the correct mean?', '["46.4", "50.36", "59", "53.6"]', 3, 'The total was 36 too small (95 − 59). Correct total = 500 + 36 = 536, mean = 53.6.', '{"0": "Subtracts the error instead of adding it.", "1": "Spreads the 36 error over 100 instead of 10.", "2": "Takes the copied value as the mean."}'),
  ('MAT-0399', 'Data interpretation and statistics', 'Pie charts', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a survey, 45 people chose tea, 60 coffee, 75 juice and 120 water. In a pie chart of these results, what angle is the juice sector?', '["75°", "25°", "90°", "112.5°"]', 2, 'Total = 300. Juice = 75/300 = 1/4 of 360° = 90°.', '{"0": "Uses the number of people as degrees.", "1": "That is the percentage of people who chose juice.", "3": "Scales by 360 ÷ 240, leaving out the coffee group."}'),
  ('MAT-0400', 'Data interpretation and statistics', 'Reading graphs', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The table gives a car''s total distance from home at each hour.
Time (h):        0    1    2    3    4
Distance (km):   0   50   80   80  140
What was its average speed for the time it was actually moving?', '["35 km/h", "46⅔ km/h", "60 km/h", "70 km/h"]', 1, 'The car did not move between 2 h and 3 h. It covered 140 km in 3 hours of moving: 140 ÷ 3 = 46⅔ km/h.', '{"0": "That includes the hour when the car was stopped.", "2": "That is the speed in the fastest hour only.", "3": "Divides 140 km by 2 hours."}'),
  ('MAT-0401', 'Data interpretation and statistics', 'Mean, median and mode', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The mean mark of 25 boys is 60. The mean mark of the whole class of 40 students is 63. What is the mean mark of the girls?', '["66", "68", "61.5", "25.5"]', 1, 'Class total = 40 × 63 = 2,520. Boys'' total = 25 × 60 = 1,500. Girls'' total = 1,020 over 15 girls = 68.', '{"0": "Adds the difference of the means (3) twice.", "2": "Averages 60 and 63.", "3": "Divides the girls'' total of 1,020 by 40 instead of 15."}'),
  ('MAT-0402', 'Probability and counting', 'Arrangements', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In how many ways can 5 people sit in a row of 5 chairs if two of them, Ali and Bano, must sit next to each other?', '["120", "24", "72", "48"]', 3, 'Glue Ali and Bano into one block: 4 units can be arranged in 4! = 24 ways, and the pair can swap: 24 × 2 = 48.', '{"0": "That is every arrangement, with no condition.", "1": "Treats Ali and Bano as one block but forgets they can swap places.", "2": "That is the number of arrangements where they are NOT together."}'),
  ('MAT-0403', 'Probability and counting', 'Arrangements', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many different arrangements are there of all the letters of the word LETTER?', '["180", "720", "360", "90"]', 0, '6 letters with E twice and T twice: 6! ÷ (2! × 2!) = 720 ÷ 4 = 180.', '{"1": "Treats all six letters as different.", "2": "Allows for only one repeated letter.", "3": "Divides by 2! three times."}'),
  ('MAT-0404', 'Probability and counting', 'Selections', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A committee of 3 is chosen from 5 men and 4 women. In how many ways can this be done if at least one woman must be included?', '["84", "40", "74", "10"]', 2, 'All committees: C(9, 3) = 84. All-male: C(5, 3) = 10. At least one woman: 84 − 10 = 74.', '{"0": "That is every possible committee, including all-male ones.", "1": "That counts committees with exactly one woman.", "3": "That is the number of all-male committees."}'),
  ('MAT-0405', 'Probability and counting', 'Complementary events', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A fair die is rolled 4 times. What is the probability of getting at least one six?', '["671/1296", "2/3", "625/1296", "1/1296"]', 0, 'P(no six in 4 rolls) = (5/6)⁴ = 625/1296. P(at least one six) = 1 − 625/1296 = 671/1296 (about 0.52).', '{"1": "Adds 1/6 four times; this double-counts outcomes with more than one six.", "2": "That is the probability of no six at all.", "3": "That is the probability of four sixes."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0406', 'Probability and counting', 'Without replacement', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two cards are drawn without replacement from a standard pack of 52. What is the probability that both are aces?', '["1/169", "1/26", "1/221", "1/2652"]', 2, 'P = 4/52 × 3/51 = 12/2652 = 1/221.', '{"0": "That is the answer with replacement: (4/52)².", "1": "Adds 4/52 to itself instead of multiplying.", "3": "Counts only one particular ordered pair of aces."}'),
  ('MAT-0407', 'Probability and counting', 'Conditional probability', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A family has two children. Given that at least one of them is a boy, what is the probability that both are boys? (Assume boys and girls are equally likely.)', '["1/2", "1/3", "1/4", "2/3"]', 1, 'Equally likely families: BB, BG, GB, GG. ''At least one boy'' leaves BB, BG, GB. Only BB has two boys: 1/3.', '{"0": "Treats the other child as independent of the given information.", "2": "That is P(both boys) before knowing anything.", "3": "That is the probability that the family has one boy and one girl."}'),
  ('MAT-0408', 'Probability and counting', 'Genetics probability', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two parents are both carriers (Aa) of a recessive condition. Their child does not have the condition. What is the probability that the child is a carrier?', '["1/2", "1/4", "3/4", "2/3"]', 3, 'Offspring: AA, Aa, aA, aa (equally likely). Unaffected leaves AA, Aa, aA; two of these three are carriers: 2/3.', '{"0": "That is P(carrier) before we know the child is unaffected.", "1": "That is the probability of the condition (aa).", "2": "That is the probability of being unaffected."}'),
  ('MAT-0409', 'Probability and counting', 'Probability with counting', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A bag has 4 red and 6 blue balls. Three are taken out at random without replacement. What is the probability that exactly two are red?', '["36/125", "1/30", "1/20", "3/10"]', 3, 'Ways: C(4, 2) × C(6, 1) = 6 × 6 = 36. Total ways: C(10, 3) = 120. P = 36/120 = 3/10.', '{"0": "That is the answer if each ball were put back (with replacement).", "1": "That is the probability that all three are red.", "2": "Counts the ways to choose the 2 red balls but forgets to choose the blue one."}'),
  ('MAT-0410', 'Probability and counting', 'Sets and Venn diagrams', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a group of 100 students, 50 study Biology, 40 Chemistry and 35 Physics. 15 study Biology and Chemistry, 10 Biology and Physics, 12 Chemistry and Physics, and 5 study all three. How many study none of the three?', '["12", "2", "7", "0"]', 2, 'By inclusion–exclusion, at least one = 50 + 40 + 35 − 15 − 10 − 12 + 5 = 93. None = 100 − 93 = 7.', '{"0": "Subtracts the pairs but forgets to add back the 5 who study all three.", "1": "Adds the ''all three'' group back twice.", "3": "Assumes every student studies at least one subject."}'),
  ('MAT-0411', 'Probability and counting', 'Selections', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A team is formed by choosing 2 of 5 doctors and 3 of 6 nurses. How many different teams are possible?', '["30", "200", "462", "2,400"]', 1, 'C(5, 2) × C(6, 3) = 10 × 20 = 200.', '{"0": "Adds C(5, 2) + C(6, 3).", "2": "Chooses any 5 of the 11 people.", "3": "Counts ordered choices (5 × 4 × 6 × 5 × 4)."}'),
  ('MAT-0412', 'Probability and counting', 'Expected value', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a game you roll a fair die. You win Rs 40 if it shows 6, and lose Rs 8 otherwise. What is your expected gain per game?', '["Rs 0 (a fair game)", "Rs 32 gain", "Rs 8 loss", "Rs 16 gain"]', 0, 'Expected gain = (1/6)(40) + (5/6)(−8) = 40/6 − 40/6 = 0.', '{"1": "Subtracts the loss from the win, ignoring how likely each is.", "2": "Looks only at the most likely result.", "3": "Treats winning and losing as equally likely."}'),
  ('MAT-0413', 'Probability and counting', 'Counting principle', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many 4-digit numbers have four different digits?', '["5,040", "4,536", "3,024", "9,000"]', 1, 'First digit: 9 choices (1–9). Then 9, 8 and 7 choices for the rest (0 is now allowed). 9 × 9 × 8 × 7 = 4,536.', '{"0": "Allows 0 as the first digit (10 × 9 × 8 × 7).", "2": "Leaves 0 out of the digits altogether (9 × 8 × 7 × 6).", "3": "That is every 4-digit number, with repeats allowed."}'),
  ('MAT-0414', 'Probability and counting', 'Counting principle', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Using the digits 1, 2, 3, 4 and 5 without repetition, how many 3-digit even numbers can be made?', '["60", "48", "24", "12"]', 2, 'The last digit is 2 or 4 (2 ways). The other two places then have 4 × 3 ways. 2 × 12 = 24.', '{"0": "That is every 3-digit number, even or odd.", "1": "Allows 4 choices for each of the first two digits.", "3": "Allows only one even digit for the last place."}'),
  ('MAT-0415', 'Probability and counting', 'Arrangements', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In how many ways can 6 people sit around a round table, if only their order around the table matters (rotations count as the same)?', '["720", "60", "24", "120"]', 3, 'Fix one person''s seat to remove rotations; the other 5 can be arranged in 5! = 120 ways.', '{"0": "Counts rotations of the same seating as different.", "1": "Also divides by 2 for reflections, which is not asked.", "2": "Fixes two people''s seats instead of one (4!)."}'),
  ('MAT-0416', 'Probability and counting', 'Two dice', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Two fair dice are rolled. What is the probability that the total is a prime number?', '["5/12", "5/11", "7/18", "1/2"]', 0, 'Prime totals 2, 3, 5, 7, 11 arise in 1 + 2 + 4 + 6 + 2 = 15 of the 36 outcomes. P = 15/36 = 5/12.', '{"1": "Counts 5 prime totals out of the 11 possible totals, but the totals are not equally likely.", "2": "Misses the total 2 (from 1 + 1).", "3": "Assumes primes and non-primes are equally likely."}'),
  ('MAT-0417', 'Probability and counting', 'Sets and Venn diagrams', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'For two events, P(A) = 0.5, P(B) = 0.4 and P(A or B) = 0.7. What is the probability that A happens but B does not?', '["0.5", "0.2", "0.1", "0.3"]', 3, 'P(A and B) = 0.5 + 0.4 − 0.7 = 0.2. P(A only) = 0.5 − 0.2 = 0.3.', '{"0": "That is P(A), which includes the overlap.", "1": "That is P(A and B), the overlap.", "2": "Subtracts P(B) from P(A)."}'),
  ('MAT-0418', 'Probability and counting', 'Complementary events', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Three people are chosen at random. Assuming every birth month is equally likely, what is the probability that at least two of them were born in the same month?', '["55/72", "1/144", "17/72", "1/4"]', 2, 'P(all different) = (12 × 11 × 10) ÷ 12³ = 1320/1728 = 55/72. P(at least two the same) = 1 − 55/72 = 17/72.', '{"0": "That is the probability that all three months are different.", "1": "That is the probability that all three share one month.", "3": "Adds 1/12 three times."}'),
  ('MAT-0419', 'Probability and counting', 'Selections', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '4 people are to be chosen from 10. Two of the 10, Dawood and Erum, refuse to be chosen together. How many choices are possible?', '["182", "210", "28", "154"]', 0, 'All groups: C(10, 4) = 210. Groups with both: choose the other 2 from 8, C(8, 2) = 28. Allowed: 210 − 28 = 182.', '{"1": "That ignores the condition.", "2": "That is the number of groups containing BOTH of them.", "3": "Subtracts the 56 groups containing exactly one of them instead of both."}'),
  ('MAT-0420', 'Probability and counting', 'Coins', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A fair coin is tossed 5 times. What is the probability of getting at least 4 heads?', '["5/32", "3/16", "1/32", "4/5"]', 1, 'P(4 heads) = C(5, 4)/32 = 5/32 and P(5 heads) = 1/32. Total = 6/32 = 3/16.', '{"0": "That is exactly 4 heads; 5 heads must be added.", "2": "That is exactly 5 heads.", "3": "Uses 4 out of 5 tosses as a probability."}'),
  ('MAT-0421', 'Probability and counting', 'Counting principle', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A code is 3 letters (A–Z, repeats allowed) followed by 2 different digits (0–9). How many codes are possible?', '["1,581,840", "1,757,600", "1,404,000", "17,666"]', 0, 'Letters: 26³ = 17,576. Digits: 10 × 9 = 90. Codes = 17,576 × 90 = 1,581,840.', '{"1": "Allows the two digits to be the same (26³ × 100).", "2": "Also stops the letters repeating (26 × 25 × 24 × 90).", "3": "Adds 26³ and 90 instead of multiplying."}'),
  ('MAT-0422', 'Sequences and patterns', 'Arithmetic sequences', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In an arithmetic sequence the 5th term is 17 and the 12th term is 38. What is the 20th term?', '["59", "65", "68", "62"]', 3, '7 steps (from term 5 to 12) add 21, so d = 3. First term = 17 − 4 × 3 = 5. 20th term = 5 + 19 × 3 = 62.', '{"0": "Uses 18 steps of 3 from the first term instead of 19.", "1": "Uses 20 steps of 3 from the first term instead of 19.", "2": "Adds 10 steps of 3 to the 12th term instead of 8."}'),
  ('MAT-0423', 'Sequences and patterns', 'Arithmetic series', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the sum of the first 25 terms of 3 + 7 + 11 + 15 + …?', '["99", "2,550", "1,275", "1,176"]', 2, 'The 25th term is 3 + 24 × 4 = 99. Sum = 25 × (3 + 99) ÷ 2 = 1,275.', '{"0": "That is the 25th term, not the sum.", "1": "Forgets to halve: 25 × (3 + 99).", "3": "Adds only 24 terms."}'),
  ('MAT-0424', 'Sequences and patterns', 'Arithmetic series', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the smallest whole number n for which 1 + 2 + 3 + … + n is greater than 500?', '["31", "32", "23", "250"]', 1, '1 + … + n = n(n + 1)/2. For n = 31 this is 496; for n = 32 it is 528. So n = 32.', '{"0": "1 + 2 + … + 31 = 496, which is not greater than 500.", "2": "Uses √500 ≈ 22.4 instead of √1000.", "3": "Divides 500 by 2."}'),
  ('MAT-0425', 'Sequences and patterns', 'Geometric sequences', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a geometric sequence the 3rd term is 12 and the 6th term is 96. What is the sum of the first 8 terms?', '["384", "765", "381", "1,530"]', 1, 'r³ = 96 ÷ 12 = 8, so r = 2 and the first term is 12 ÷ 4 = 3. Sum of 8 terms = 3(2⁸ − 1) ÷ (2 − 1) = 3 × 255 = 765.', '{"0": "That is the 8th term.", "2": "Adds only 7 terms.", "3": "Uses first term 6 instead of 3."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0426', 'Sequences and patterns', 'Geometric series', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The series 18 + 12 + 8 + … continues for ever. What is its sum?', '["38", "27", "36", "54"]', 3, 'Common ratio r = 12/18 = 2/3. Sum to infinity = a ÷ (1 − r) = 18 ÷ (1/3) = 54.', '{"0": "That is the sum of the first three terms only.", "1": "Uses 18 ÷ (1 − 1/3) with ratio 1/3 instead of 2/3.", "2": "Doubles the first term."}'),
  ('MAT-0427', 'Sequences and patterns', 'Number patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A sequence starts with 2, and each term after that is 3 times the previous term minus 1. What is the 5th term?', '["122", "41", "365", "162"]', 0, '2 → 3×2 − 1 = 5 → 14 → 41 → 122. The 5th term is 122.', '{"1": "That is the 4th term.", "2": "That is the 6th term.", "3": "Multiplies by 3 without subtracting 1 (2 × 3⁴)."}'),
  ('MAT-0428', 'Sequences and patterns', 'Number patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a sequence, each term after the second is the sum of the two terms before it. The 5th term is 23 and the 6th term is 37. What is the 1st term?', '["5", "9", "4", "14"]', 2, 'Work backwards: 4th = 37 − 23 = 14, 3rd = 23 − 14 = 9, 2nd = 14 − 9 = 5, 1st = 9 − 5 = 4.', '{"0": "That is the 2nd term.", "1": "That is the 3rd term.", "3": "That is the 4th term."}'),
  ('MAT-0429', 'Sequences and patterns', 'Number patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The sequence 2, 6, 12, 20, 30, … continues in the same way. What is its 15th term?', '["210", "240", "225", "272"]', 1, 'The terms are 1×2, 2×3, 3×4, …, so the nth term is n(n + 1). 15th term = 15 × 16 = 240.', '{"0": "That is 14 × 15, the 14th term.", "2": "Takes the nth term as n².", "3": "That is the 16th term."}'),
  ('MAT-0430', 'Sequences and patterns', 'Digit puzzles', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many digits are printed altogether when the pages of a book are numbered from 1 to 250?', '["750", "639", "642", "640"]', 2, 'Pages 1–9: 9 digits. Pages 10–99: 90 × 2 = 180. Pages 100–250: 151 × 3 = 453. Total 9 + 180 + 453 = 642.', '{"0": "Assumes every page number has 3 digits.", "1": "Uses 150 three-digit page numbers instead of 151.", "3": "Counts pages 10–99 as 89 numbers instead of 90."}'),
  ('MAT-0431', 'Sequences and patterns', 'Number patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the units digit of 1! + 2! + 3! + … + 50!?', '["0", "9", "4", "3"]', 3, 'From 5! onwards every factorial ends in 0. 1 + 2 + 6 + 24 = 33, so the units digit is 3.', '{"0": "Every term from 5! on ends in 0, but the first four do not.", "1": "Adds 1 + 2 + 6 only.", "2": "Takes the units digit of 4! alone."}'),
  ('MAT-0432', 'Sequences and patterns', 'Arithmetic series', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the sum of all the odd numbers from 51 to 149 inclusive?', '["5,000", "4,900", "9,900", "5,100"]', 0, 'There are (149 − 51) ÷ 2 + 1 = 50 odd numbers, with mean (51 + 149) ÷ 2 = 100. Sum = 50 × 100 = 5,000.', '{"1": "Uses 49 terms instead of 50.", "2": "Adds every whole number from 51 to 149, not just the odd ones.", "3": "Counts 51 terms instead of 50."}'),
  ('MAT-0433', 'Sequences and patterns', 'Repeating patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '1/7 = 0.142857142857… What is the 100th digit after the decimal point?', '["7", "5", "4", "8"]', 3, 'The block 142857 has 6 digits. 100 = 6 × 16 + 4, so the 100th digit is the 4th digit of the block: 8.', '{"0": "Assumes 100 is a multiple of 6, so takes the last digit of the block.", "1": "Uses the 5th place in the repeating block.", "2": "Uses the 2nd place in the repeating block."}'),
  ('MAT-0434', 'Sequences and patterns', 'Calendar patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '1 March of a certain year is a Monday. On what day of the week is 1 June of the same year?', '["Tuesday", "Monday", "Wednesday", "Thursday"]', 0, 'From 1 March to 1 June: 31 (March) + 30 (April) + 31 (May) = 92 days = 13 weeks + 1 day. One day after Monday is Tuesday.', '{"1": "Assumes three months make a whole number of weeks.", "2": "Counts 93 days (gives April 31 days).", "3": "Counts 94 days."}'),
  ('MAT-0435', 'Sequences and patterns', 'Growing patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A row of squares is made from matchsticks: 1 square uses 4 matchsticks, 2 squares in a row use 7, 3 squares use 10, and so on. What is the largest number of squares that can be made in a row with 100 matchsticks?', '["25", "33", "34", "32"]', 1, 'n squares need 3n + 1 matchsticks. 3n + 1 ≤ 100 gives n ≤ 33. 33 squares use 100 exactly.', '{"0": "Uses 4 matchsticks for every square.", "2": "34 squares need 3 × 34 + 1 = 103 matchsticks.", "3": "Solves 3n + 4 ≤ 100 instead of 3n + 1 ≤ 100."}'),
  ('MAT-0436', 'Sequences and patterns', 'Growing patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Dots are arranged in triangles: 1, 3, 6, 10, … dots. How many dots are in the 20th triangle?', '["200", "231", "210", "190"]', 2, 'The nth triangular number is n(n + 1)/2. 20 × 21 ÷ 2 = 210.', '{"0": "Uses 20 × 10, forgetting the extra row.", "1": "That is the 21st triangle.", "3": "That is the 19th triangle."}'),
  ('MAT-0437', 'Sequences and patterns', 'Number patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is 1² + 2² + 3² + … + 10²?', '["3,025", "55", "385", "285"]', 2, 'Sum of squares = n(n + 1)(2n + 1)/6 = 10 × 11 × 21 ÷ 6 = 385.', '{"0": "That is (1 + 2 + … + 10)², the square of the sum.", "1": "That is 1 + 2 + … + 10, without squaring.", "3": "Adds the squares only up to 9²."}'),
  ('MAT-0438', 'Sequences and patterns', 'Letter patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What letter comes next: A, C, F, J, O, …?', '["U", "T", "V", "P"]', 0, 'The gaps grow by one: +2, +3, +4, +5. Next is +6: O (15th letter) + 6 = U (21st letter).', '{"1": "Adds 5 again instead of 6.", "2": "Adds 7.", "3": "Adds 1."}'),
  ('MAT-0439', 'Sequences and patterns', 'Mixed patterns', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the next number: 2, 3, 5, 9, 17, 33, …?', '["49", "65", "66", "64"]', 1, 'Each term is double the previous one minus 1 (the gaps 1, 2, 4, 8, 16 double). 2 × 33 − 1 = 65.', '{"0": "Adds 16 again instead of doubling the gap.", "2": "Doubles 33 but forgets to subtract 1.", "3": "Doubles 32 instead of following the rule."}'),
  ('MAT-0440', 'Sequences and patterns', 'Arithmetic sequences', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many terms are there in the sequence 7, 11, 15, …, 403?', '["99", "101", "396", "100"]', 3, 'Number of terms = (403 − 7) ÷ 4 + 1 = 99 + 1 = 100.', '{"0": "Forgets to count the first term.", "1": "Adds 1 twice.", "2": "That is the difference between the last and first terms."}'),
  ('MAT-0441', 'Sequences and patterns', 'Geometric series', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A ball is dropped from a height of 16 m. Each bounce rises to 3/4 of the height it fell from. What total distance does the ball travel before it comes to rest (in theory)?', '["64 m", "128 m", "48 m", "112 m"]', 3, 'Falls: 16 + 12 + 9 + … = 64 m. Rises: 12 + 9 + … = 48 m. Total = 64 + 48 = 112 m.', '{"0": "Uses only the fall distances, 16 ÷ (1 − 3/4).", "1": "Counts the first 16 m fall twice.", "2": "Adds only the upward bounces."}'),
  ('MAT-0442', 'Sequences and patterns', 'Geometric sequences', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Money grows by 10% each year, compounded yearly. After how many whole years is it first more than double the original amount?', '["10", "7", "8", "7.2"]', 2, '1.1⁷ ≈ 1.949 and 1.1⁸ ≈ 2.144. So it first passes double after 8 years.', '{"0": "Uses simple interest (10 × 10% = 100%).", "1": "After 7 years it is 1.1⁷ ≈ 1.95 times, still short of double.", "3": "Uses the rule of 72 (72 ÷ 10), an estimate, not a whole number of years."}'),
  ('MAT-0443', 'Quantitative comparison', 'Pie charts', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A family spends Rs 60,000 a month. In a pie chart of its spending, the transport sector has an angle of 54°.
Quantity A: The monthly spending on transport
Quantity B: Rs 9,500
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, 'Transport = 54/360 × 60,000 = 0.15 × 60,000 = Rs 9,000, which is less than Rs 9,500. B is greater.', '{"0": "54° is 15% of the circle, so transport is Rs 9,000.", "2": "Rs 9,000 ≠ Rs 9,500.", "3": "The angle and total fix the amount."}'),
  ('MAT-0444', 'Quantitative comparison', 'Successive percentages', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A jacket''s price has a 10% discount and a 15% sales tax applied to it.
Quantity A: The final price if the discount is applied first and then the tax
Quantity B: The final price if the tax is applied first and then the discount
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, 'Both orders multiply the price by 0.90 × 1.15 = 1.035, and multiplication can be done in any order. Equal.', '{"0": "Both give 1.035 times the price.", "1": "Both give 1.035 times the price.", "3": "Although the price is not given, the two results are always equal."}'),
  ('MAT-0445', 'Quantitative comparison', 'Sets', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'In a group of 60 people, 35 like tea and 30 like coffee. Everyone likes at least one of the two.
Quantity A: The number who like both
Quantity B: The number who like only coffee
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, 'Both = 35 + 30 − 60 = 5. Only coffee = 30 − 5 = 25. B is greater.', '{"0": "Only 5 like both.", "2": "5 ≠ 25.", "3": "The overlap is fixed because everyone likes at least one."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0446', 'Quantitative comparison', 'Grouped data', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'House prices (in thousands of rupees) are grouped:
20–29: 5 houses   30–39: 12 houses   40–49: 8 houses
(Prices are whole numbers of thousands.)
Quantity A: The range of the 25 prices (in thousands)
Quantity B: 30
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, 'The cheapest house costs 20–29 and the dearest 40–49, so the range is between 40 − 29 = 11 and 49 − 20 = 29. It is always less than 30, so B is greater.', '{"0": "The largest possible range is 49 − 20 = 29.", "2": "The range can be at most 29.", "3": "Although the exact range is unknown, it is always below 30."}'),
  ('MAT-0447', 'Quantitative comparison', 'Averages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Rainfall (cm) in eight districts was 12, 18, 9, x, 20, 14, 16 and 11, where x is a positive number.
Quantity A: The median rainfall
Quantity B: 15 cm
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'Without x the values are 9, 11, 12, 14, 16, 18, 20. The median is the mean of the 4th and 5th of the eight values: 13 if x ≤ 12, (x + 14)/2 if 12 ≤ x ≤ 16, and 15 if x ≥ 16. So A can be less than or equal to 15: cannot be determined.', '{"0": "The median is never more than 15.", "1": "If x ≥ 16 the median is exactly 15.", "2": "If x is small the median is 13."}'),
  ('MAT-0448', 'Quantitative comparison', 'Fractions', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'x > 0
Quantity A: x/(x + 1)
Quantity B: (x + 1)/(x + 2)
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, 'B − A = 1/((x + 1)(x + 2)), which is positive for every x > 0. So B is always greater.', '{"0": "Try x = 1: A = 1/2 and B = 2/3.", "2": "B − A = 1/((x + 1)(x + 2)) is never 0.", "3": "The difference has the same sign for every positive x."}'),
  ('MAT-0449', 'Quantitative comparison', 'Powers', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: 99¹⁰⁰
Quantity B: 100⁹⁹
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, 'A ÷ B = 99 × (99/100)⁹⁹ ≈ 99 × 0.37 ≈ 37, so A is far larger. (Compare logs: 100 × log 99 ≈ 199.56 and 99 × log 100 = 198.)', '{"1": "A larger base does not win here; the extra power of 99 matters more.", "2": "They differ by a factor of about 37.", "3": "Both are fixed numbers."}'),
  ('MAT-0450', 'Quantitative comparison', 'Roots', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: √11 − √10
Quantity B: √12 − √11
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, '√(n+1) − √n = 1/(√(n+1) + √n), which gets smaller as n grows. So √11 − √10 > √12 − √11.', '{"1": "The gaps between square roots shrink as the numbers grow.", "2": "A = 1/(√11 + √10) and B = 1/(√12 + √11) have different denominators.", "3": "Both are fixed numbers."}'),
  ('MAT-0451', 'Quantitative comparison', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'n is an odd positive integer.
Quantity A: The remainder when n² is divided by 4
Quantity B: 1
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, 'An odd number is 2k + 1, and (2k + 1)² = 4k² + 4k + 1 leaves remainder 1 on division by 4. Equal.', '{"0": "The remainder is always exactly 1.", "1": "The remainder is never 0 for odd n.", "3": "It is 1 for every odd n."}'),
  ('MAT-0452', 'Quantitative comparison', 'Variables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'x² = 2x
Quantity A: x
Quantity B: 1
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'x² = 2x gives x(x − 2) = 0, so x = 0 or x = 2. One is less than 1 and the other greater, so it cannot be determined.', '{"0": "x could be 0.", "1": "x could be 2.", "2": "Neither solution equals 1."}'),
  ('MAT-0453', 'Quantitative comparison', 'Variables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'a and b are positive and a + b = 10.
Quantity A: ab
Quantity B: 25
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'ab is largest when a = b = 5, giving 25. Otherwise it is smaller (e.g. 4 × 6 = 24). So A can be equal to or less than B.', '{"0": "ab can never exceed 25 when a + b = 10.", "1": "a = b = 5 gives exactly 25.", "2": "a = 4, b = 6 gives only 24."}'),
  ('MAT-0454', 'Quantitative comparison', 'Averages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'x is a number.
Quantity A: The mean of x, x + 2, x + 4, …, x + 20
Quantity B: x + 10
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, 'There are 11 evenly spaced numbers, so the mean is the middle one, x + 10. Equal for every x.', '{"0": "The mean is exactly x + 10.", "1": "The mean is exactly x + 10.", "3": "Although x is unknown, both quantities are x + 10."}'),
  ('MAT-0455', 'Quantitative comparison', 'Probability', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: The probability of at least one head when 3 fair coins are tossed
Quantity B: The probability of not rolling a 6 with one fair die
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, 'A = 1 − (1/2)³ = 7/8 = 0.875. B = 5/6 ≈ 0.833. A is greater.', '{"1": "7/8 = 0.875 is more than 5/6 ≈ 0.833.", "2": "7/8 and 5/6 are different.", "3": "Both are fixed probabilities."}'),
  ('MAT-0456', 'Quantitative comparison', 'Geometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A circle has diameter 20 cm. A square has a diagonal of 20 cm.
Quantity A: The circumference of the circle
Quantity B: The perimeter of the square
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, 'Circumference = 20π ≈ 62.8 cm. Square side = 20/√2 ≈ 14.14 cm, perimeter ≈ 56.6 cm. A is greater.', '{"1": "40√2 ≈ 56.6 is less than 20π ≈ 62.8.", "2": "The two lengths differ by about 6 cm.", "3": "Both can be calculated."}'),
  ('MAT-0457', 'Quantitative comparison', 'Powers', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: 2⁻³
Quantity B: 3⁻²
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, '2⁻³ = 1/8 and 3⁻² = 1/9. 1/8 > 1/9, so A is greater.', '{"1": "1/8 is more than 1/9.", "2": "1/8 ≠ 1/9.", "3": "Both are fixed numbers."}'),
  ('MAT-0458', 'Quantitative comparison', 'Variables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'xy < 0
Quantity A: (x + y)²
Quantity B: (x − y)²
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, '(x − y)² − (x + y)² = −4xy. Since xy < 0, this is positive, so B is always greater.', '{"0": "With x = 1, y = −1: A = 0 and B = 4.", "2": "They differ by −4xy, which is not 0 here.", "3": "The sign of −4xy is fixed when xy < 0."}'),
  ('MAT-0459', 'Quantitative comparison', 'Variables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '0 < x < 1
Quantity A: √x
Quantity B: x²
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, 'For 0 < x < 1, √x > x > x². E.g. x = 1/4: √x = 1/2 and x² = 1/16. A is greater.', '{"1": "Squaring a number between 0 and 1 makes it smaller; taking the root makes it larger.", "2": "They are equal only at x = 0 or 1, which are excluded.", "3": "Every x in the range gives the same order."}'),
  ('MAT-0460', 'Quantitative comparison', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: 17 × 19
Quantity B: 18²
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 1, '17 × 19 = (18 − 1)(18 + 1) = 18² − 1 = 323, and 18² = 324. B is greater.', '{"0": "17 × 19 = 323 is one less than 324.", "2": "They differ by 1.", "3": "Both are fixed numbers."}'),
  ('MAT-0461', 'Quantitative comparison', 'Geometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A rectangle has an area of 36 cm².
Quantity A: Its perimeter (in cm)
Quantity B: 24
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'A 6 × 6 square has perimeter 24; any other shape with area 36 has a larger perimeter (4 × 9 gives 26). So A can be equal to or greater than B.', '{"0": "A 6 × 6 square gives exactly 24.", "1": "The perimeter is never less than 24 for this area.", "2": "A 4 × 9 rectangle gives 26."}'),
  ('MAT-0462', 'Quantitative comparison', 'Geometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A triangle has sides 7 cm, 24 cm and 25 cm.
Quantity A: Its area (in cm²)
Quantity B: 84
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, '7² + 24² = 49 + 576 = 625 = 25², so the triangle is right-angled with legs 7 and 24. Area = ½ × 7 × 24 = 84. Equal.', '{"0": "The area is exactly 84.", "1": "The area is exactly 84.", "3": "The three sides fix the triangle, so its area is fixed."}'),
  ('MAT-0463', 'Quantitative comparison', 'Factorials', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Quantity A: The number of ways to choose 3 people from 10
Quantity B: 5!
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, 'C(10, 3) = 10 × 9 × 8 ÷ 6 = 120 and 5! = 120. Equal.', '{"0": "Both are 120.", "1": "Both are 120.", "3": "Both are fixed numbers."}'),
  ('MAT-0464', 'Quantitative comparison', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'p is a prime number greater than 2.
Quantity A: The remainder when p² − 1 is divided by 8
Quantity B: 0
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 2, 'p is odd, so p² − 1 = (p − 1)(p + 1), a product of two consecutive even numbers. One of them is a multiple of 4, so the product is a multiple of 8. Remainder 0: equal.', '{"0": "The remainder is always 0.", "1": "A remainder cannot be less than 0.", "3": "It is 0 for every odd prime."}'),
  ('MAT-0465', 'Quantitative comparison', 'Averages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The data set is 3, 5, x, 11, where 5 < x < 11.
Quantity A: The mean of the data
Quantity B: The median of the data
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 3, 'Mean = (19 + x)/4 and median = (5 + x)/2. Mean − median = (9 − x)/4, which is positive for x < 9, zero at x = 9 and negative for x > 9. Cannot be determined.', '{"0": "Fails for x = 10 (mean 7.25, median 7.5).", "1": "Fails for x = 6 (mean 6.25, median 5.5).", "2": "Equal only when x = 9."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0466', 'Quantitative comparison', 'Percentages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', '200 g of a 10% salt solution is mixed with 300 g of a 20% salt solution.
Quantity A: The percentage of salt in the mixture
Quantity B: 15%
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, 'Salt = 20 g + 60 g = 80 g in 500 g, which is 16%. A is greater (more of the stronger solution was used).', '{"1": "15% would need equal amounts of each solution.", "2": "80 out of 500 is 16%, not 15%.", "3": "The amounts are all given."}'),
  ('MAT-0467', 'Quantitative comparison', 'Variables', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'x > y > 0
Quantity A: x/y
Quantity B: (x + 1)/(y + 1)
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, 'x/y − (x + 1)/(y + 1) = (x − y)/(y(y + 1)), which is positive when x > y > 0. A is greater.', '{"1": "Adding 1 to the top and bottom moves a fraction greater than 1 towards 1.", "2": "They are equal only when x = y.", "3": "The difference has a fixed sign when x > y > 0."}'),
  ('MAT-0468', 'Quantitative comparison', 'Sequences', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'The sequence 3, 6, 12, 24, … doubles each time.
Quantity A: The 10th term
Quantity B: The sum of the first 9 terms
Compare Quantity A with Quantity B.', '["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the information given"]', 0, '10th term = 3 × 2⁹ = 1,536. Sum of the first 9 = 3(2⁹ − 1) = 1,533. A is greater, by 3.', '{"1": "Each term of a doubling sequence beats the sum of all the terms before it.", "2": "They differ by 3.", "3": "Both are fixed numbers."}'),
  ('MAT-0469', 'Data sufficiency', 'Choosing two statements', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the price of one pencil?
(i) 3 pens and 2 pencils cost Rs 130 altogether.
(ii) A pen costs Rs 20 more than a pencil.
(iii) The shop sold 50 items that day.
(iv) Pencils are cheaper than pens.
Which two statements together give enough information to answer the question?', '["i and iii", "ii and iv", "iii and iv", "i and ii"]', 3, 'From (i) and (ii): 3(p + 20) + 2p = 130, so 5p = 70 and a pencil costs Rs 14.', '{"0": "The number of items sold says nothing about prices; (i) alone has many solutions.", "1": "Both only compare the prices; no actual amount is given.", "2": "Neither gives any price."}'),
  ('MAT-0470', 'Data sufficiency', 'Choosing two statements', 'moderate', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the mean height of the students in a class?
(i) The class has 12 boys and 18 girls.
(ii) The girls'' mean height is 150 cm and the boys'' mean height is 160 cm.
(iii) The girls'' mean height is 150 cm.
(iv) The tallest student is 172 cm.
Which two statements together give enough information to answer the question?', '["i and iii", "iii and iv", "ii and iv", "i and ii"]', 3, 'With (i) and (ii): total = 12 × 160 + 18 × 150 = 1,920 + 2,700 = 4,620 cm over 30 students, a mean of 154 cm.', '{"0": "The boys'' mean height is still unknown.", "1": "Neither gives the boys'' heights or the class size.", "2": "Without the numbers of boys and girls the two means cannot be weighted."}'),
  ('MAT-0471', 'Data sufficiency', 'Choosing two statements', 'easy', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How far did a car travel on a journey?
(i) The journey took 3 hours.
(ii) The car''s average speed was 60 km/h.
(iii) The car left at 9 a.m.
(iv) The car arrived at 12 noon.
Which two statements together give enough information to answer the question?', '["i and ii", "ii and iii", "iii and iv", "i and iv"]', 0, 'Distance = speed × time = 60 × 3 = 180 km, so (i) and (ii) are enough.', '{"1": "The departure time alone does not give the length of the journey.", "2": "These give the time (3 hours) but not the speed.", "3": "Both give only the time; the speed is unknown."}'),
  ('MAT-0472', 'Data sufficiency', 'Choosing two statements', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A triangle has a right angle. What is its area?
(i) Its longest side is 13 cm.
(ii) One of the sides next to the right angle is 5 cm.
(iii) Its perimeter is 30 cm.
(iv) One of its angles is 90°.
Which two statements together give enough information to answer the question?', '["iii and iv", "ii and iv", "i and ii", "i and iv"]', 2, 'With (i) and (ii): the other short side is √(13² − 5²) = 12 cm, so the area is ½ × 5 × 12 = 30 cm².', '{"0": "Many right triangles have a perimeter of 30 cm (e.g. sides 5, 12, 13 or about 10, 10, 14.1), with different areas.", "1": "One short side alone does not fix the other.", "3": "Many right triangles have a 13 cm hypotenuse (e.g. 5, 12 or 9, √88)."}'),
  ('MAT-0473', 'Data sufficiency', 'Choosing two statements', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the value of the whole number n?
(i) n is a prime number.
(ii) n is between 20 and 30.
(iii) n − 3 is a multiple of 10.
(iv) n is odd.
Which two statements together give enough information to answer the question?', '["i and ii", "ii and iii", "i and iii", "i and iv"]', 1, 'With (ii) and (iii): the only number between 20 and 30 that is 3 more than a multiple of 10 is 23.', '{"0": "Both 23 and 29 are primes between 20 and 30.", "2": "13, 23, 43 and others are primes that are 3 more than a multiple of 10.", "3": "Almost every prime is odd; many values remain."}'),
  ('MAT-0474', 'Data sufficiency', 'Inequalities', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Is x > y?
Statement 1: x² > y²
Statement 2: x + y > 0
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1 allows x = −3, y = 1 (no) and x = 3, y = 1 (yes). Statement 2 allows x = 1, y = 2 (no) and x = 2, y = 1 (yes). Together: x² − y² = (x − y)(x + y) > 0 with x + y > 0 forces x − y > 0. Yes.', '{"0": "x² > y² allows x = −3, y = 1, where x < y.", "1": "x + y > 0 allows x = 1, y = 2.", "3": "Together they force x > y."}'),
  ('MAT-0475', 'Data sufficiency', 'Quadratic equations', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the value of the integer n?
Statement 1: n² − 4n − 21 = 0
Statement 2: n > 0
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1 gives (n − 7)(n + 3) = 0, so n = 7 or −3. Statement 2 alone allows any positive n. Together n = 7.', '{"0": "The quadratic has two roots, 7 and −3.", "1": "n > 0 allows many integers.", "3": "Together only n = 7 is left."}'),
  ('MAT-0476', 'Data sufficiency', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Is the positive integer n divisible by 12?
Statement 1: n is divisible by 4.
Statement 2: n is divisible by 6.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1 allows 8 (no) and 12 (yes); statement 2 allows 6 (no) and 12 (yes). Together n is a multiple of LCM(4, 6) = 12. Yes.', '{"0": "n = 8 is divisible by 4 but not by 12.", "1": "n = 6 is divisible by 6 but not by 12.", "3": "Together n must be a multiple of 12."}'),
  ('MAT-0477', 'Data sufficiency', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Is the positive integer n divisible by 24?
Statement 1: n is divisible by 4.
Statement 2: n is divisible by 6.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 3, 'Together the statements only make n a multiple of LCM(4, 6) = 12. n = 12 is not divisible by 24, but n = 24 is. Not sufficient (4 × 6 = 24 is a trap: the LCM is 12).', '{"0": "n = 4 and n = 24 both fit statement 1.", "1": "n = 6 and n = 24 both fit statement 2.", "2": "Together n = 12 (no) and n = 24 (yes) both fit."}'),
  ('MAT-0478', 'Data sufficiency', 'Geometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the area of a rectangle?
Statement 1: Its perimeter is 28 cm.
Statement 2: Its diagonal is 10 cm.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1: l + w = 14, which allows 7 × 7 = 49 or 4 × 10 = 40. Statement 2: l² + w² = 100, which allows 6 × 8 = 48 or 1 × √99 ≈ 9.95. Together: (l + w)² = l² + w² + 2lw gives 196 = 100 + 2lw, so lw = 48 cm².', '{"0": "Perimeter 28 allows several areas, e.g. 49 and 40.", "1": "Diagonal 10 allows several areas, e.g. 48 and about 9.95.", "3": "Together the area is fixed at 48 cm²."}'),
  ('MAT-0479', 'Data sufficiency', 'Averages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the mean of the three numbers a, b and c?
Statement 1: a + b = 2c
Statement 2: 2a + 2b + 2c = 36
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 1, 'Statement 2 alone gives a + b + c = 18, so the mean is 6. Statement 1 alone only says the mean is c, which is unknown.', '{"0": "Statement 1 makes the mean equal to c, but c is unknown.", "2": "Statement 2 alone is already enough.", "3": "Statement 2 alone gives the total 18."}'),
  ('MAT-0480', 'Data sufficiency', 'Ages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How old is Sara now?
Statement 1: In 5 years Sara will be twice as old as she was 10 years ago.
Statement 2: Sara''s brother is 3 years older than she is.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 0, 'Statement 1: s + 5 = 2(s − 10), so s = 25. Statement 2 gives no age without the brother''s age.', '{"1": "Statement 2 relates two unknown ages.", "2": "Statement 1 alone is already enough.", "3": "Statement 1 alone gives 25."}'),
  ('MAT-0481', 'Data sufficiency', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Is xy > 0? (x and y are not zero.)
Statement 1: x/y > 0
Statement 2: x + y > 0
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 0, 'x/y > 0 means x and y have the same sign, so xy > 0. Statement 2 allows x = 3, y = −1 (xy < 0) and x = 1, y = 2 (xy > 0).', '{"1": "x = 3, y = −1 gives a positive sum but a negative product.", "2": "Statement 1 alone is already enough.", "3": "Statement 1 alone answers it."}'),
  ('MAT-0482', 'Data sufficiency', 'Absolute value', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the value of x?
Statement 1: |x − 2| = 3
Statement 2: |x + 3| = 2
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1: x = 5 or −1. Statement 2: x = −1 or −5. The only value in both is −1.', '{"0": "Statement 1 allows 5 and −1.", "1": "Statement 2 allows −1 and −5.", "3": "Together only x = −1 fits."}'),
  ('MAT-0483', 'Data sufficiency', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Is the integer k odd?
Statement 1: k² + k is even.
Statement 2: 3k + 2 is odd.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 1, 'k² + k = k(k + 1) is even for every integer, so statement 1 tells us nothing. If 3k + 2 is odd, 3k is odd, so k is odd: statement 2 is enough.', '{"0": "k² + k is even for every integer k.", "2": "Statement 2 alone is already enough.", "3": "Statement 2 alone answers it."}'),
  ('MAT-0484', 'Data sufficiency', 'Percentages', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'By what percentage did the price of a book change over two years?
Statement 1: In the first year it rose by 20%.
Statement 2: In the second year it fell by 20%.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Each statement gives only one year''s change. Together the multiplier is 1.2 × 0.8 = 0.96: a 4% fall.', '{"0": "The second year''s change is unknown.", "1": "The first year''s change is unknown.", "3": "Together they fix the change at −4%."}'),
  ('MAT-0485', 'Data sufficiency', 'Probability', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'A bag holds only red and blue balls. What is the probability that a ball picked at random is red?
Statement 1: There are 12 blue balls.
Statement 2: There are 4 more red balls than blue balls.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1 leaves the number of red balls open. Statement 2 alone allows 5 red, 1 blue (5/6) or 6 red, 2 blue (3/4). Together: 16 red, 12 blue, P = 16/28 = 4/7.', '{"0": "The number of red balls is unknown.", "1": "''4 more'' fixes a difference, not a ratio.", "3": "Together the probability is 4/7."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MAT-0486', 'Data sufficiency', 'Rates', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How long do A and B take to do a job working together?
Statement 1: A alone takes 6 hours.
Statement 2: B works twice as fast as A.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1 gives A''s rate only; statement 2 gives a ratio only. Together: B takes 3 h, combined rate 1/6 + 1/3 = 1/2 job per hour, so 2 hours.', '{"0": "B''s rate is unknown.", "1": "Without a time for A, the ratio gives no actual time.", "3": "Together they give 2 hours."}'),
  ('MAT-0487', 'Data sufficiency', 'Statistics', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Five different integers are listed. What is their median?
Statement 1: The three smallest of them are 2, 5 and 9.
Statement 2: Their mean is 10.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 0, 'With five numbers in order, the median is the 3rd. If the three smallest are 2, 5 and 9, the 3rd is 9: statement 1 alone is enough. A mean of 10 allows many medians.', '{"1": "A mean of 10 allows medians such as 9 and 10.", "2": "Statement 1 alone is already enough.", "3": "Statement 1 alone fixes the 3rd value."}'),
  ('MAT-0488', 'Data sufficiency', 'Geometry', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Is triangle PQR right-angled?
Statement 1: Two of its sides are 5 cm and 12 cm.
Statement 2: One of its sides is 13 cm.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1: the third side could be 13 (right-angled) or 10 (not). Statement 2: sides 5, 12, 13 (right-angled) or 13, 13, 13 (not). Together the sides are 5, 12, 13 and 5² + 12² = 13²: yes.', '{"0": "With sides 5 and 12, the third side could be 10.", "1": "A 13, 13, 13 triangle is not right-angled.", "3": "Together the sides are 5, 12, 13."}'),
  ('MAT-0489', 'Data sufficiency', 'Number properties', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the remainder when the positive integer n is divided by 15?
Statement 1: n leaves remainder 2 when divided by 3.
Statement 2: n leaves remainder 4 when divided by 5.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1 allows remainders 2, 5, 8, 11, 14; statement 2 allows 4, 9, 14. Together only 14 fits (e.g. n = 14, 29, 44).', '{"0": "n = 2 and n = 5 both leave 2 on division by 3.", "1": "n = 4 and n = 9 both leave 4 on division by 5.", "3": "Together the remainder is always 14."}'),
  ('MAT-0490', 'Data sufficiency', 'Algebra', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'x and y are integers. What is x + y?
Statement 1: x² − y² = 15
Statement 2: x − y = 3
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1 allows (8, 7) with sum 15 and (4, 1) with sum 5. Statement 2 allows many pairs. Together (x − y)(x + y) = 15 with x − y = 3 gives x + y = 5.', '{"0": "x = 8, y = 7 and x = 4, y = 1 both fit, with different sums.", "1": "x − y = 3 allows many pairs.", "3": "Together x + y = 5."}'),
  ('MAT-0491', 'Data sufficiency', 'Linear equations', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'What is the value of 2x + 3y?
Statement 1: 4x + 6y = 18
Statement 2: x = 3
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 0, 'Statement 1 is 2(2x + 3y) = 18, so 2x + 3y = 9 even though x and y are not known separately. Statement 2 leaves y unknown.', '{"1": "With x = 3, y is still unknown.", "2": "Statement 1 alone is already enough.", "3": "Statement 1 alone gives 9."}'),
  ('MAT-0492', 'Data sufficiency', 'Inequalities', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'Is a > b?
Statement 1: a/b > 1
Statement 2: b > 0
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'Statement 1 allows a = 4, b = 2 (yes) and a = −4, b = −2 (no, since −4 < −2). Statement 2 says nothing about a. Together, multiplying a/b > 1 by positive b gives a > b. Yes.', '{"0": "a = −4, b = −2 gives a/b = 2 > 1 but a < b.", "1": "b > 0 says nothing about a.", "3": "Together they force a > b."}'),
  ('MAT-0493', 'Data sufficiency', 'Linear equations', 'hard', 'Markhor Prep original question. AKU MBBS admission test, Science and Mathematics Reasoning section (AKU practice resource: Mathematics Reasoning)', 'How many students are in the class?
Statement 1: If 3 students sit on each bench, 2 students have no seat.
Statement 2: If 4 students sit on each bench, 3 benches are left empty.
Do the statements give enough information to answer the question?', '["Statement 1 alone is sufficient, but statement 2 alone is not", "Statement 2 alone is sufficient, but statement 1 alone is not", "Both statements together are sufficient, but neither alone is", "The statements together are not sufficient"]', 2, 'With b benches: statement 1 says s = 3b + 2 and statement 2 says s = 4(b − 3). Each alone has many solutions. Together 3b + 2 = 4b − 12, so b = 14 and s = 44.', '{"0": "The number of benches is unknown.", "1": "The number of benches is unknown.", "3": "Together they give 44 students."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

-- Every new Mathematics question is listed in the AKU bank under its own chapter.
INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'aku', id, subject, chapter FROM questions WHERE subject = 'Mathematics' AND id BETWEEN 'MAT-0246' AND 'MAT-0493';

INSERT INTO question_counters (prefix, n) VALUES ('MAT', 493) ON CONFLICT (prefix) DO UPDATE SET n = max(n, 493);
